insert into public.exercises (name, description, category, difficulty, equipment_required, restrictions, alternatives, muscle_groups, primary_muscle, slug, image_start_url, image_end_url, media_source, media_license, media_author)
values
  ('Aducción de Cadera en Máquina', 'Este es un ejercicio de aislamiento que se realiza en una máquina específica para fortalecer los músculos aductores, es decir, la musculatura de la parte interna de los muslos. Ayuda a mejorar la estabilidad de la cadera y a equilibrar la fuerza de las piernas. Cómo realizarlo: Preparación: Siéntate en la máquina con la espalda y la cadera completamente apoyadas en el respaldo. Coloca la parte interna de tus muslos o rodillas contra las almohadillas acolchadas. Ajusta la palanca de la máquina para establecer un rango de movimiento inicial que te resulte cómodo pero que genere un ligero estiramiento. Ejecución: Usando la fuerza de la parte interna de tus muslos, junta las piernas de manera lenta y controlada. Haz una breve pausa en el punto de máxima contracción (cuando las almohadillas cas', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["adductors","gluteos"]'::jsonb, 'adductors', 'aduccion-de-cadera-en-maquina', 'https://wger.de/media/exercise-images/12/4a42cc6f-648d-40cc-a72a-c49dd47e1667.webp', 'https://wger.de/media/exercise-images/12/4a42cc6f-648d-40cc-a72a-c49dd47e1667.webp', 'wger.de', 'CC-BY-SA 3', 'flori'),
  ('Sostenimiento Lateral Isométrico', 'Toma un par de mancuernas, extiende los brazos hacia los lados y mantén la posición el mayor tiempo que puedas.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'sostenimiento-lateral-isometrico', 'https://wger.de/media/exercise-images/31/92f6451b-f89d-49d6-9531-8970ea420d97.png', 'https://wger.de/media/exercise-images/31/92f6451b-f89d-49d6-9531-8970ea420d97.png', 'wger.de', 'CC-BY-SA 3', 'GrosseHund'),
  ('Rollout Abdominal con Barra', 'Cómo realizarlo: Preparación: Carga una barra con discos redondos (de 5 o 10 kg es suficiente para que ruede bien). Arrodíllate en el suelo, preferiblemente sobre una colchoneta. Agarra la barra con las palmas hacia abajo (agarre prono) y las manos separadas al ancho de los hombros. El Despliegue (Rollout): Manteniendo el abdomen y los glúteos fuertemente contraídos, rueda la barra hacia adelante de manera lenta y controlada. Extiende tu cuerpo en una línea lo más recta posible, llegando tan lejos como puedas sin que tu espalda baja se arquee. El Regreso: Haz una breve pausa en el punto de máxima extensión. Luego, usa la fuerza de tus abdominales para jalar la barra hacia ti, revirtiendo el movimiento hasta volver a la posición inicial de forma controlada.', 'core', 'intermediate', '["barbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["lower_back","core"]'::jsonb, 'lower_back', 'rollout-abdominal-con-barra', 'https://wger.de/media/exercise-images/41/34b37423-269f-43d4-9d29-d2a90eeaa6b4.png', 'https://wger.de/media/exercise-images/41/34b37423-269f-43d4-9d29-d2a90eeaa6b4.png', 'wger.de', 'CC-BY-SA 4', 'sevae'),
  ('Extensión de triceps', 'Coloque la barra sobre la cabeza con un agarre en pronación estrecho. Baje el antebrazo detrás de la parte superior del brazo con los codos sobre la cabeza. Extienda el antebrazo por encima de la cabeza. Baja y repite.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["back_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'extension-de-triceps', 'https://wger.de/media/exercise-images/50/695ced5c-9961-4076-add2-cb250d01089e.png', 'https://wger.de/media/exercise-images/50/44cf2c72-a78a-4d5e-a8b5-a02c6ea61fb4.jpg', 'wger.de', 'CC-BY-SA 4', 'sevae'),
  ('Curl de Muñeca con Barra (Agarre Supino)', 'Este ejercicio es fundamental para desarrollar los músculos flexores del antebrazo (la parte interna o de abajo), que son cruciales para la fuerza de agarre. Instrucciones: Sentado en un banco, apoya tus antebrazos sobre los muslos y sujeta una barra con las palmas mirando hacia arriba (agarre supino). Las muñecas deben quedar libres, por delante de las rodillas. Deja que la barra baje para estirar bien la muñeca y, desde ese punto, flexiónala para subir el peso lo más que puedas. Aprieta con fuerza en la cima y luego baja de manera lenta y controlada para maximizar el trabajo', 'accessory', 'intermediate', '["barbell","bench"]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-de-muneca-con-barra-agarre-supino', 'https://wger.de/media/exercise-images/51/f1730f56-7aca-4566-8338-3e42b1bee6e1.webp', 'https://wger.de/media/exercise-images/51/f1730f56-7aca-4566-8338-3e42b1bee6e1.webp', 'wger.de', 'CC-BY-SA 4', 'burenl'),
  ('Press de Banca', 'Acuéstate en un banco plano. La barra debe estar directamente sobre tus ojos, las rodillas deben estar ligeramente flexionadas y los pies firmemente apoyados en el suelo. Concéntrate, respira profundamente y agarra la barra con una apertura mayor a la anchura de tus hombros. Bájala lentamente hasta que toque brevemente tu pecho a la altura de los pezones. Empuja la barra hacia arriba. Si entrenas con un peso elevado, es aconsejable tener un ayudante ( spotter ) que pueda asistirte si no puedes levantar el peso por ti mismo. Con la anchura del agarre también puedes controlar qué parte del pecho se trabaja más: Agarre ancho: musculatura externa del pecho. Agarre cerrado: musculatura interna del pecho y tríceps.', 'accessory', 'intermediate', '["barbell","bench"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'press-de-banca', 'https://wger.de/media/exercise-images/192/Bench-press-1.png', 'https://wger.de/media/exercise-images/192/Bench-press-2.png', 'wger.de', 'CC-BY-SA 3', 'sistab2'),
  ('Press de banca con mancuernas', 'Es un ejercicio multiarticular de fuerza y de hipertrofia destinado al desarrollo del tren superior, específicamente el pecho. Al usar mancuernas en lugar de barra, se corrige el desequilibrio de fuerza entre ambos lados del cuerpo y se permite un movimiento más natural y amigable para las articulaciones del hombro. Preparación y Posición Inicial: Siéntate en el extremo de un banco plano con una mancuerna apoyada verticalmente en cada muslo. Túmbate hacia atrás con cuidado mientras impulsas las mancuernas con las rodillas hacia tu pecho. El "Leg Drive" y Postura: Apoya los pies firmemente en el suelo. Retrae las escápulas (junta los omóplatos contra el banco) y mantén un ligero arco lumbar natural. Posición de Salida: Empuja las mancuernas hacia el techo. Tus muñecas deben estar alineadas ', 'accessory', 'intermediate', '["bench","dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["lower_back","pecho"]'::jsonb, 'lower_back', 'press-de-banca-con-mancuernas', 'https://wger.de/media/exercise-images/97/Dumbbell-bench-press-1.png', 'https://wger.de/media/exercise-images/75/7b700f5d-17fc-41a9-bd41-e98e45c15768.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press de Banca con Agarre Cerrado', 'Esta variante del press de banca pone un mayor énfasis en los tríceps y la parte interna del pecho. La posición inicial en el banco es la misma que en un press normal, pero con estas diferencias clave: Agarre: Sujeta la barra con un agarre cerrado, aproximadamente al ancho de los hombros (unos 20-30 cm de separación entre las manos). Movimiento: Baja la barra de forma controlada hacia la parte baja de tu pecho o el esternón (más abajo que en el press convencional), manteniendo los codos cerca de tu cuerpo. Desde ahí, empuja con fuerza hacia arriba hasta extender los brazos, enfocándote en la contracción de los tríceps.', 'accessory', 'intermediate', '["barbell","bench"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'press-de-banca-con-agarre-cerrado', 'https://wger.de/media/exercise-images/88/Narrow-grip-bench-press-1.png', 'https://wger.de/media/exercise-images/76/9abec4e4-90ba-44f9-9e6e-5e35f7273078.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Jalón Alto Inclinado con Mancuernas', 'Este ejercicio se enfoca en la parte alta de la espalda, los trapecios y los deltoides posteriores. Descripción: Sostén un par de mancuernas e inclina el torso ligeramente hacia adelante, manteniendo la espalda recta . Desde esa posición, jala las mancuernas verticalmente hacia la parte alta de tu pecho. La clave es liderar el movimiento con los codos, elevándolos lo más alto y hacia afuera posible. Asegúrate de que tus codos siempre permanezcan por encima de tus muñecas durante el jalón. Baja de forma controlada.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["deltoids"]'::jsonb, 'deltoids', 'jalon-alto-inclinado-con-mancuernas', 'https://wger.de/media/exercise-images/79/da58dfbf-748a-461b-891e-3d6bc9cc4be2.png', 'https://wger.de/media/exercise-images/79/da58dfbf-748a-461b-891e-3d6bc9cc4be2.png', 'wger.de', 'CC-BY-SA 3', 'lakerbeezel'),
  ('Remo con mancuernas', 'Con las mancuernas en la mano, flexiona la cadera hasta que las manos cuelguen justo por debajo de las rodillas (similar a la posición inicial de pierna recta). Mantenga constante el ángulo de la parte superior del cuerpo mientras contrae los músculos dorsales para llevar los codos hacia atrás, pellizcando los omóplatos en la parte superior. Intenta no levantarte en cada repetición, comprueba que las manos quedan por debajo de las rodillas en cada repetición.', 'accessory', 'intermediate', '["bench","dumbbell"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-con-mancuernas', 'https://wger.de/media/exercise-images/81/a751a438-ae2d-4751-8d61-cef0e9292174.png', 'https://wger.de/media/exercise-images/81/a751a438-ae2d-4751-8d61-cef0e9292174.png', 'wger.de', 'CC-BY-SA 4', 'sebk'),
  ('Remo Inclinado con Barra (agarre prono)', 'Sujeta la barra con un agarre prono (palmas hacia abajo) y las manos un poco más abiertas que el ancho de tus hombros. Inclina tu torso hacia adelante desde la cadera, manteniendo la espalda completamente recta y las rodillas ligeramente flexionadas, hasta que el torso quede casi paralelo al suelo. La barra debe colgar con los brazos extendidos. Desde esa posición, y manteniendo el torso fijo, jala la barra hacia la parte baja de tu abdomen. Mantén los codos cerca del cuerpo, aprieta los músculos de la espalda por un segundo en la cima del movimiento y luego baja la barra de forma lenta y controlada hasta la posición inicial.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-inclinado-con-barra-agarre-prono', 'https://wger.de/media/exercise-images/109/Barbell-rear-delt-row-1.png', 'https://wger.de/media/exercise-images/109/Barbell-rear-delt-row-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Remo inclinado con agarre invertido', 'Igual que el remo normal , pero con un agarre invertido (las palmas apuntando hacia delante): Agarra la barra con un agarre amplio (algo más que la anchura de los hombros) e inclínate hacia delante. Tu tronco no queda del todo paralelo al suelo, sino que forma un ligero ángulo. El pecho permanece hacia fuera durante todo el ejercicio. Ahora tira de la barra con un movimiento rápido hacia el ombligo, no más arriba. Baja lentamente a la posición inicial. No te balancees con el cuerpo y mantén los brazos pegados al cuerpo.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-inclinado-con-agarre-invertido', 'https://wger.de/media/exercise-images/110/Reverse-grip-bent-over-rows-1.png', 'https://wger.de/media/exercise-images/110/Reverse-grip-bent-over-rows-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Curl con barra', 'Sostén la barra a la anchura de los hombros, con la espalda recta, los hombros ligeramente hacia atrás y los brazos estirados. Flexiona los brazos y levanta la pesa con un movimiento rápido. Sin pausa, baja la barra con un movimiento lento y controlado. No balancees el cuerpo durante el ejercicio; todo el trabajo lo realizan los bíceps, que son los únicos músculos que deben moverse (presta atención a los codos).', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-con-barra', 'https://wger.de/media/exercise-images/74/Bicep-curls-1.png', 'https://wger.de/media/exercise-images/74/Bicep-curls-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Curl de bíceps con mancuerna', 'Sujeta dos pesas, los brazos estirados, las manos a los lados, las palmas hacia dentro. Flexiona los brazos y sube el peso con un movimiento rápido. Al mismo tiempo, gira los brazos 90 grados al principio del movimiento. En el punto más alto, gira un poco las pesas hacia fuera. Sin pausa, bájalas lentamente.No permitas que tu cuerpo se balancee durante el ejercicio, todo el trabajo lo realizan los bíceps, que son los únicos músculos que deben moverse (presta atención a los codos).', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["back_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-de-biceps-con-mancuerna', 'https://wger.de/media/exercise-images/81/Biceps-curl-1.png', 'https://wger.de/media/exercise-images/81/Biceps-curl-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Curl de biceps con barra Z', 'Sostenga la barra SZ a la altura de los hombros, la espalda recta, los hombros ligeramente hacia atrás, los brazos estirados. Dobla los brazos, elevando el peso, con un movimiento rápido. Sin pausa, baja la barra con un movimiento lento y controlado. No dejes que tu cuerpo se balancee durante el ejercicio, todo el trabajo lo hacen los bíceps, que son los únicos músculos que deben moverse (presta atención a los codos).', 'accessory', 'intermediate', '["sz-bar"]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-de-biceps-con-barra-z', 'https://wger.de/media/exercise-images/94/6dee2f60-aea2-4f2d-9bf6-aef50c4f9483.png', 'https://wger.de/media/exercise-images/94/6dee2f60-aea2-4f2d-9bf6-aef50c4f9483.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Curl de Bíceps en Polea', 'Párate a uno o dos pasos de una polea en su posición más baja y sujeta la barra o el agarre con las palmas hacia arriba (agarre supino). Manteniendo los codos fijos a los costados de tu cuerpo, sube el peso con un movimiento relativamente rápido y potente, contrayendo el bíceps en la parte alta. La clave del ejercicio está en la bajada: regresa a la posición inicial de forma lenta y controlada, resistiendo la tensión constante del cable.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-de-biceps-en-polea', 'https://wger.de/media/exercise-images/129/Standing-biceps-curl-1.png', 'https://wger.de/media/exercise-images/129/Standing-biceps-curl-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press de Pecho en Máquina', 'Este ejercicio es excelente para trabajar los músculos pectorales de forma segura y controlada, ideal para principiantes o para aislar el músculo al final de una rutina. Instrucciones: Siéntate en la máquina con la espalda firmemente apoyada en el respaldo. Ajusta la altura del asiento para que los agarres queden a la altura de la parte media de tu pecho. Empuja los agarres hacia adelante hasta que tus brazos estén extendidos (pero sin bloquear los codos), enfocándote en apretar los músculos del pecho en la contracción final. Regresa de forma lenta y controlada a la posición inicial.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'press-de-pecho-en-maquina', 'https://wger.de/media/exercise-images/129/b263c968-e067-4750-916a-d8758a7df23e.webp', 'https://wger.de/media/exercise-images/129/dbad8cd0-5eeb-4de2-8d9e-80c7770735fd.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Aperturas en máquina', 'Posición inicial Sentado en la máquina "Peck deck" con la espalda pegada al respaldo, los antebrazos bien apoyados contra las piezas acolchadas previstas para este fin. La parte superior de los brazos debe estar paralela al suelo y en línea con los hombros.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'aperturas-en-maquina', 'https://wger.de/media/exercise-images/98/Butterfly-machine-2.png', 'https://wger.de/media/exercise-images/98/Butterfly-machine-1.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Gemelos en prensa', 'Sentado sobre el aparato, la parte alta de los muslos apoyada sobre el asiento, la punta de los pies sobre la calza, los tobillos en flexión pasiva: - Efectuar una extensión de los pies (flexión plantar).', 'accessory', 'intermediate', '[]'::jsonb, '["knee_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'gemelos-en-prensa', 'https://wger.de/media/exercise-images/146/8b284904-d072-4381-a256-4c81d8fd9c1f.png', 'https://wger.de/media/exercise-images/146/8b284904-d072-4381-a256-4c81d8fd9c1f.png', 'wger.de', 'CC-BY-SA 4', 'nate303303'),
  ('Dominadas con Agarre Supino', 'Esta es una variante de la dominada que se caracteriza por el tipo de agarre, lo cual involucra de forma muy activa a los bíceps junto con los músculos de la espalda (dorsales). A menudo resulta más accesible que la dominada con agarre prono (pull-up). Instrucciones: Sujeta la barra con las palmas de las manos mirando hacia ti (agarre supino), con una separación similar al ancho de tus hombros. Desde una posición colgado con los brazos extendidos, jala tu cuerpo hacia arriba hasta que tu mentón o barbilla sobrepase la barra. Baja de forma controlada hasta la extensión completa para terminar la repetición.', 'accessory', 'intermediate', '["pull-up_bar"]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps","espalda"]'::jsonb, 'biceps', 'dominadas-con-agarre-supino', 'https://wger.de/media/exercise-images/152/6c1a7459-266d-491a-bd50-7cbaea2bc771.png', 'https://wger.de/media/exercise-images/152/b2c5a9f9-8beb-41f7-841c-9664d22a427e.png', 'wger.de', 'CC0', 'BFad07'),
  ('Jalón al Pecho con Agarre Cerrado', 'Esta variante del jalón, con un agarre más estrecho, se enfoca en la densidad de la espalda y permite un mayor rango de movimiento para la contracción de los dorsales. Instrucciones: Sujeta la barra con un agarre cerrado (manos más juntas que el ancho de los hombros) y prono (palmas mirando hacia abajo/lejos de ti). Inclina tu torso ligeramente hacia atrás. Jala la barra verticalmente hacia la parte superior de tu pecho, manteniendo los codos siempre cerca de tus costados. Al final del recorrido, aprieta la espalda y junta los omóplatos. Regresa a la posición inicial de forma controlada.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'jalon-al-pecho-con-agarre-cerrado', 'https://wger.de/media/exercise-images/158/0d51a0f2-622f-434b-beb8-1a003c54712a.png', 'https://wger.de/media/exercise-images/158/02e8a7c3-dc67-434e-a4bc-77fdecf84b49.webp', 'wger.de', 'CC-BY-SA 3', 'tuckerm'),
  ('Pullover con Mancuerna', 'Este ejercicio clásico es excelente para estirar y trabajar simultáneamente los músculos del pecho (pectorales) y la espalda (dorsales), además de ayudar a la expansión de la caja torácica. Instrucciones: Acuéstate de forma transversal (atravesado) sobre un banco plano, apoyando únicamente la parte alta de tu espalda y hombros. Mantén los pies firmes en el suelo para darte estabilidad y la cadera a un nivel bajo. Sujeta una mancuerna con ambas manos y extiéndela sobre tu pecho. Con una ligera pero constante flexión en los codos, baja la mancuerna en un arco amplio por detrás de tu cabeza hasta sentir un estiramiento profundo. Regresa a la posición inicial siguiendo el mismo arco y de forma controlada.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","espalda","pecho"]'::jsonb, 'pectorals', 'pullover-con-mancuerna', 'https://wger.de/media/exercise-images/161/b9b1803e-2817-40bf-8ac7-e398ca86d8b4.png', 'https://wger.de/media/exercise-images/161/b9b1803e-2817-40bf-8ac7-e398ca86d8b4.png', 'wger.de', 'CC-BY-SA 3', 'powerade69'),
  ('Abdominales', 'Acuéstese boca arriba en el suelo con las rodillas dobladas. Flexione los hombros hacia la pelvis. Las manos pueden estar detrás o al costado del cuello o cruzadas sobre el pecho. Repita', 'core', 'intermediate', '["gym_mat"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'abdominales', 'https://wger.de/media/exercise-images/91/Crunches-1.png', 'https://wger.de/media/exercise-images/91/Crunches-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Abdominales en Banco Inclinado', 'Este ejercicio aumenta la intensidad del trabajo abdominal y de los flexores de cadera gracias al ángulo del banco. Instrucciones: Acuéstate en un banco inclinado, asegurando firmemente tus pies en los soportes de la parte superior. Coloca las manos a los lados de la cabeza (sin jalar el cuello) o cruzadas sobre el pecho. Contrae el abdomen y levanta tu torso "enrollando" la espalda, hasta que tus codos se acerquen a las rodillas. Baja de forma lenta y controlada a la posición inicial, sin dejarte caer. (Nota: Para un crunch inclinado, solo se levantan los hombros y la parte alta de la espalda del banco, es un movimiento mucho más corto).', 'core', 'intermediate', '["incline_bench"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'abdominales-en-banco-inclinado', 'https://wger.de/media/exercise-images/56/Decline-crunch-1.png', 'https://wger.de/media/exercise-images/56/Decline-crunch-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Peso Muerto Convencional', 'Considerado uno de los ejercicios de fuerza más completos, es fundamental para desarrollar la cadena posterior (espalda, glúteos, isquiotibiales) y la fuerza general de todo el cuerpo. La técnica correcta es crucial. Instrucciones: Párate con los pies separados al ancho de las caderas, con la barra sobre la mitad de tus pies (casi tocando tus canillas/espinillas). Agáchate manteniendo la espalda completamente recta y el pecho erguido; sujeta la barra justo por fuera de tus piernas (puedes usar un agarre prono o mixto). Para levantar, empuja el suelo con las piernas y extiende la cadera y las rodillas simultáneamente, manteniendo la barra siempre pegada a tu cuerpo. En la posición final, párate completamente erguido y aprieta los glúteos, sin hiperextender la espalda hacia atrás . Baja la b', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'peso-muerto-convencional', 'https://wger.de/media/exercise-images/184/1709c405-620a-4d07-9658-fade2b66a2df.jpeg', 'https://wger.de/media/exercise-images/184/1709c405-620a-4d07-9658-fade2b66a2df.jpeg', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press de Banca Declinado con Barra', 'Esta variante del press de banca pone un mayor énfasis en la porción inferior de los músculos pectorales. Instrucciones Posición: Acuéstate en un banco declinado y asegura tus piernas firmemente en los soportes. Sujeta la barra con un agarre un poco más ancho que tus hombros. Descenso: Baja la barra de forma controlada hasta que toque la parte baja de tu pecho o el esternón. Ascenso: Empuja la barra con fuerza hacia arriba hasta extender los brazos (sin bloquear los codos), concentrándote en apretar la parte baja del pectoral.', 'accessory', 'intermediate', '["barbell","bench"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'press-de-banca-declinado-con-barra', 'https://wger.de/media/exercise-images/100/Decline-bench-press-1.png', 'https://wger.de/media/exercise-images/100/Decline-bench-press-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Fondos en Paralelas', 'Los fondos son un ejercicio fundamental con peso corporal para desarrollar fuerza de empuje, enfocándose en el pecho, los tríceps y los hombros. La forma en que se realiza determina qué músculo se lleva el mayor énfasis. Instrucciones Posición: Sostén tu cuerpo sobre las barras paralelas con los brazos completamente extendidos. Descenso: Flexiona los codos y baja tu cuerpo de forma controlada hasta que tus hombros queden ligeramente por debajo de tus codos, sintiendo un estiramiento en el pecho. Ascenso: Empuja con fuerza para volver a la posición inicial hasta extender los brazos. Para enfocar en el pecho: Usa un agarre más ancho, inclina el torso hacia adelante durante el movimiento y permite que los codos se abran un poco. Para enfocar en los tríceps: Usa un agarre al ancho de los hombr', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["triceps","pecho"]'::jsonb, 'triceps', 'fondos-en-paralelas', 'https://wger.de/media/exercise-images/194/34600351-8b0b-4cb0-8daa-583537be15b0.png', 'https://wger.de/media/exercise-images/194/34600351-8b0b-4cb0-8daa-583537be15b0.png', 'wger.de', 'CC0', 'BFad07'),
  ('Fondos entre Bancos', 'Esta es una excelente variante de los fondos para aislar y trabajar los tríceps utilizando únicamente bancos y tu peso corporal. Instrucciones Posición: Coloca dos bancos paralelos entre sí. Siéntate en uno y apoya las palmas de tus manos en el borde, junto a tu cadera. Extiende las piernas y apoya los talones sobre el otro banco. Levanta la cadera del banco, sosteniendo tu peso con los brazos. Descenso: Manteniendo los codos apuntando hacia atrás, flexiónalos para bajar tu cuerpo de forma controlada hasta que sientas un buen estiramiento en los tríceps (aproximadamente a un ángulo de 90 grados en el codo). Ascenso: Empuja con fuerza a través de las palmas de tus manos para volver a la posición inicial, contrayendo los tríceps. Evita extender por completo los codos en la parte alta para ma', 'accessory', 'intermediate', '["bench"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'fondos-entre-bancos', 'https://wger.de/media/exercise-images/83/Bench-dips-1.png', 'https://wger.de/media/exercise-images/83/Bench-dips-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Sentadilla con disco', 'Tipos de sentadillas con disco Goblet Squat: Es la sentadilla con disco más común, donde el disco se sostiene a la altura del pecho, ayudando a mantener una buena postura y mejorando la estabilidad del tobillo. Overhead Plate Squat: En esta variación, el disco se mantiene por encima de la cabeza durante todo el movimiento de la sentadilla, lo que aumenta la demanda de movilidad y estabilidad del hombro.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["knee_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'sentadilla-con-disco', 'https://wger.de/media/exercise-images/203/1c052351-2af0-4227-aeb0-244008e4b0a8.jpeg', 'https://wger.de/media/exercise-images/203/2ab30113-4e08-4d39-9d23-d901ce2c0971.jpeg', 'wger.de', 'CC-BY-SA 4', 'ataraxie67'),
  ('Zancadas Caminando con Mancuernas', 'Esta es la variante dinámica de las zancadas. Al avanzar con cada paso en lugar de permanecer en el mismo sitio, se incrementa el trabajo de estabilización, equilibrio y coordinación. Instrucciones Posición: De pie, con la espalda recta, sostén una mancuerna en cada mano a los costados de tu cuerpo. Zancada: Da un paso largo hacia adelante. Baja la cadera de forma controlada hasta que ambas rodillas se flexionen en un ángulo de aproximadamente 90 grados. La rodilla de atrás debe quedar cerca del suelo, sin tocarlo. Avance: Manteniendo el torso erguido, impúlsate hacia adelante: presiona con el talón del pie delantero para ponerte de pie y dar inmediatamente el siguiente paso con la otra pierna. Continúa "caminando" con zancadas de forma fluida.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'zancadas-caminando-con-mancuernas', 'https://wger.de/media/exercise-images/113/Walking-lunges-1.png', 'https://wger.de/media/exercise-images/206/6ec66efd-e74f-4142-bed1-0a0ac74e3294.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Cruce de Poleas para Pecho', 'Este ejercicio de aislamiento es excelente para lograr una fuerte contracción y estiramiento en los músculos pectorales, enfocándose en la parte interna del pecho. Instrucciones Posición: En una estación de poleas, ajusta ambas poleas a una posición alta. Toma un agarre en cada mano, da un paso al frente para generar tensión y mantén el torso ligeramente inclinado hacia adelante. Movimiento: Con una ligera pero constante flexión en los codos, junta las manos al frente y abajo de tu cuerpo en un movimiento de arco amplio, como si estuvieras abrazando un árbol. Contracción: Aprieta el pecho con fuerza en el punto de máxima contracción. Regresa de forma lenta y controlada a la posición inicial, sintiendo cómo se estira el pectoral.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'cruce-de-poleas-para-pecho', 'https://wger.de/media/exercise-images/122/Incline-cable-flyes-1.png', 'https://wger.de/media/exercise-images/122/Incline-cable-flyes-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Aperturas con Mancuernas', 'Este es un ejercicio de aislamiento clásico, excelente para estirar las fibras musculares del pecho y lograr una fuerte contracción, ideal para trabajar la amplitud pectoral. Instrucciones Posición: Acuéstate en un banco plano con los pies firmes en el suelo y la espalda bien apoyada. Sostén las mancuernas directamente sobre tu pecho con las palmas de las manos enfrentadas. Apertura: Manteniendo una ligera y constante flexión en los codos, baja las mancuernas hacia los lados en un arco amplio y controlado, hasta que sientas un buen estiramiento en el pecho. Cierre: Regresa a la posición inicial siguiendo el mismo arco y apretando los pectorales, como si estuvieras dando un gran abrazo. El movimiento debe ser fluido y controlado.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'aperturas-con-mancuernas', 'https://wger.de/media/exercise-images/238/2fc242d3-5bdd-4f97-99bd-678adb8c96fc.png', 'https://wger.de/media/exercise-images/238/c6464fb3-1924-4ff1-adfa-fd36da9b5d13.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press Francés con Barra SZ', 'Este ejercicio, popularmente conocido como "rompecráneos" ( skullcrusher ), es uno de los más efectivos para añadir masa y fuerza a los tríceps. El uso de la barra SZ (o EZ) reduce la tensión sobre las muñecas en comparación con una barra recta. Instrucciones Posición: Acuéstate en un banco plano. Sujeta una barra SZ sobre tu pecho con un agarre cerrado (manos en las curvas interiores de la barra) y los brazos extendidos. Descenso: Manteniendo la parte superior de los brazos inmóvil y perpendicular al suelo, flexiona únicamente los codos para bajar la barra de forma controlada en dirección a tu frente. Ascenso: Justo antes de que la barra toque tu frente, empújala de vuelta a la posición inicial extendiendo los codos. Concéntrate en apretar los tríceps al final del movimiento.', 'accessory', 'intermediate', '["bench","sz-bar"]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'press-frances-con-barra-sz', 'https://wger.de/media/exercise-images/84/Lying-close-grip-triceps-press-to-chin-1.png', 'https://wger.de/media/exercise-images/84/Lying-close-grip-triceps-press-to-chin-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Elevaciones frontales', 'Para ejecutar el ejercicio, el levantador se para con los pies separados al ancho de los hombros y las pesas o los mangos de resistencia se sostienen a los lados con un agarre en pronación (por encima de la cabeza). El movimiento consiste en llevar los brazos por delante del cuerpo a la altura de los ojos y con sólo una ligera flexión del codo. Esto aísla el músculo deltoides anterior (frente al hombro) y utiliza el deltoides anterior para levantar el peso. Al levantar es importante mantener el cuerpo inmóvil para que el deltoides anterior se utilice por completo; si el peso no se puede levantar estando quieto, entonces es demasiado pesado y se necesita un peso menor. Es importante mantener una ligera flexión en el codo al levantar, ya que mantener el codo trabado agregará tensión a la art', 'accessory', 'intermediate', '["barbell","dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'elevaciones-frontales', 'https://wger.de/media/exercise-images/256/b7def5bc-2352-499b-b9e5-fff741003831.png', 'https://wger.de/media/exercise-images/256/b7def5bc-2352-499b-b9e5-fff741003831.png', 'wger.de', 'CC-BY-SA 3', 'Manu, wikipedia'),
  ('Sentadilla Frontal', 'Contrario a la creencia popular, esta variante de la sentadilla pone un énfasis mucho mayor en los cuádriceps y en la fuerza del core (abdominales y espalda alta), ya que la posición de la barra obliga a mantener el torso extremadamente erguido. Instrucciones Posición: Sostén la barra sobre la parte frontal de tus hombros (deltoides). Puedes usar un agarre de levantamiento olímpico ("clean grip", con los codos apuntando al frente) o cruzando los brazos para estabilizar la barra. Descenso: Manteniendo el pecho y los codos elevados en todo momento, baja a una sentadilla profunda. El torso debe permanecer lo más vertical posible durante todo el recorrido. Ascenso: Empuja con fuerza a través de tus piernas (enfocándote en los cuádriceps) para volver a la posición inicial.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["glutes","gluteos"]'::jsonb, 'glutes', 'sentadilla-frontal', 'https://wger.de/media/exercise-images/191/Front-squat-1-857x1024.png', 'https://wger.de/media/exercise-images/191/Front-squat-2-857x1024.png', 'wger.de', 'CC-BY-SA 3', 'sistab2'),
  ('Puente de glúteos', 'Túmbate boca arriba con las caderas y las rodillas flexionadas y los pies en el suelo. Desde esta posición, eleva los glúteos del suelo hasta una altura en la que tu cuerpo forme una línea recta desde las rodillas hasta los hombros. Para hacer el ejercicio más intenso, puedes añadir peso dejando que una barra repose sobre tus caderas mientras realizas el movimiento, o puedes apoyar los pies sobre una superficie algo más elevada, como un escalón o un banco.', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["glutes","gluteos"]'::jsonb, 'glutes', 'puente-de-gluteos', 'https://wger.de/media/exercise-images/265/7528acb4-b2cc-4b75-b6ae-d514cbd4f78b.png', 'https://wger.de/media/exercise-images/265/7528acb4-b2cc-4b75-b6ae-d514cbd4f78b.png', 'wger.de', 'CC-BY-SA 4', 'tdprice12'),
  ('Curl Martillo', 'Esta variante del curl utiliza un agarre neutro (como si sostuvieras un martillo) para enfocar el trabajo en el músculo braquial (ubicado debajo del bíceps) y el antebrazo (braquiorradial), lo que ayuda a dar más grosor y densidad al brazo. Instrucciones Posición: De pie o sentado, sostén un par de mancuernas a los costados de tu cuerpo con las palmas de las manos mirándose entre sí (agarre neutro). Movimiento: Manteniendo los codos fijos a los costados de tu torso, levanta las mancuernas hasta la altura de los hombros. La clave es no rotar las muñecas en ningún momento; la orientación de las palmas no cambia. Tempo: Sube el peso de forma potente y bájalo de manera lenta y controlada para maximizar la tensión muscular. Evita balancear el cuerpo.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-martillo', 'https://wger.de/media/exercise-images/86/Bicep-hammer-curl-1.png', 'https://wger.de/media/exercise-images/86/Bicep-hammer-curl-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Biceps concentrado martillo con cable', 'Ejecución 1. Realice la posición inicial. 2. Mantenga el agarre firme en todo momento, suba hasta la altura de los hombros, y hasta que ambos brazos queden flexionados. Exhale y contraiga los bíceps. 3. Luego baje lentamente, buscando que sus brazos se encuentren totalmente extendidos. En este punto inhale. 4. Repita las veces que desee.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'biceps-concentrado-martillo-con-cable', 'https://wger.de/media/exercise-images/138/Hammer-curls-with-rope-1.png', 'https://wger.de/media/exercise-images/138/Hammer-curls-with-rope-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Fortalecedor de Agarre', 'Esta herramienta, comúnmente llamada "hand grip", está diseñada para aislar y desarrollar la fuerza de agarre ( crushing strength ) y los músculos flexores del antebrazo. Instrucciones Posición: Sostén el "hand grip" firmemente en una mano. Contracción: Aprieta con la máxima fuerza posible, intentando que los dos mangos se toquen. Concéntrate en la presión que ejercen tus dedos y la palma de tu mano. Regreso: Sostén la contracción por uno o dos segundos y luego abre la mano de forma lenta y controlada. Es crucial resistir la tensión del resorte en la fase de apertura para trabajar el músculo de forma completa.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'fortalecedor-de-agarre', 'https://wger.de/media/exercise-images/279/36605bc8-d7e1-43e1-87c1-b9cb50db62b2.webp', 'https://wger.de/media/exercise-images/279/36605bc8-d7e1-43e1-87c1-b9cb50db62b2.webp', 'wger.de', 'CC-BY-SA 4', 'vince63'),
  ('Flexiones en pino', 'La flexión en pino, también llamada flexión vertical o flexión invertida, es un tipo de flexión en el que el cuerpo se coloca en posición de pino. Para un pino real, el ejercicio se realiza de forma libre, manteniéndose en el aire. Para desarrollar la fuerza hasta lograr el equilibrio adecuado, los pies a menudo se apoyan contra una pared, los sujeta un compañero o se aseguran de alguna otra forma para evitar la caída. Las flexiones en pino requieren una fuerza considerable, así como equilibrio y control si se realizan de forma libre.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["triceps","hombros"]'::jsonb, 'triceps', 'flexiones-en-pino', 'https://wger.de/media/exercise-images/282/f6121ac9-330e-4ed7-8219-91ce246bf871.png', 'https://wger.de/media/exercise-images/282/f6121ac9-330e-4ed7-8219-91ce246bf871.png', 'wger.de', 'CC0', 'BFad07'),
  ('Saltos al Pecho', 'Este es un ejercicio pliométrico de alta intensidad diseñado para desarrollar la máxima potencia y explosividad en el tren inferior. Instrucciones Carga: De pie, con los pies al ancho de los hombros, baja rápidamente a una media sentadilla para tomar impulso. Explosión: Desde el fondo de la sentadilla, salta verticalmente con la mayor fuerza posible. En el punto más alto del salto, lleva las rodillas hacia el pecho (en una posición agrupada o "tuck"). Aterrizaje: Aterriza de forma suave sobre la parte delantera de los pies, flexionando inmediatamente las rodillas y la cadera para absorber el impacto. Desde ahí, puedes encadenar la siguiente repetición.', 'cardio', 'beginner', '[]'::jsonb, '["knee_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gemelos","piernas"]'::jsonb, 'hamstrings', 'saltos-al-pecho', 'https://wger.de/media/exercise-images/285/4141e8b2-d9f2-4597-8ef0-7768127fd0ec.png', 'https://wger.de/media/exercise-images/285/4141e8b2-d9f2-4597-8ef0-7768127fd0ec.png', 'wger.de', 'CC-BY-SA 4', 'nate303303'),
  ('Hollow hold', 'Colócate sobre una esterilla y túmbate boca arriba. Contrae los abdominales, estira los brazos y las piernas y elévalos (la cabeza y los hombros también se elevan). Asegúrate de que la zona lumbar permanezca en contacto con la esterilla.', 'core', 'intermediate', '["gym_mat"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lower_back","core"]'::jsonb, 'lower_back', 'hollow-hold', 'https://wger.de/media/exercise-images/297/b10d3341-baa8-49ab-b462-5b3529389aac.png', 'https://wger.de/media/exercise-images/297/b10d3341-baa8-49ab-b462-5b3529389aac.png', 'wger.de', 'CC0', 'Behrooz'),
  ('Extensiones lumbares a 45°', 'Túmbate sobre el cojín de hiperextensiones con el ombligo en el borde delantero, dejando que la parte superior del cuerpo cuelgue libremente. Tensa todos los músculos de la espalda y eleva el torso hasta quedar en horizontal, pero no más alto. Desciende lentamente, manteniendo un flujo constante de los músculos.', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["lower_back"]'::jsonb, 'lower_back', 'extensiones-lumbares-a-45', 'https://wger.de/media/exercise-images/301/2d5c2f99-b8ff-4095-b515-4c2a85afde70.png', 'https://wger.de/media/exercise-images/128/Hyperextensions-1.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Polichilenas', 'Párese con los pies juntos y los brazos a los lados Salte a una posición con las piernas abiertas y las manos tocandose por encima de la cabeza Repita', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'polichilenas', 'https://wger.de/media/exercise-images/320/6c9124b6-3551-47a8-9c22-20141c8b9c53.png', 'https://wger.de/media/exercise-images/320/85a075aa-53ff-4d61-bad3-5f47e14e0f8e.png', 'wger.de', 'CC-BY-SA 4', 'student1234'),
  ('Aperturas en polea', 'Este ejercicio trabaja y tensa todo el músculo del pecho. Este entrenamiento de pecho es bueno, pero el equipo generalmente solo se encuentra en gimnasios públicos.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'aperturas-en-polea', 'https://wger.de/media/exercise-images/71/Cable-crossover-2.png', 'https://wger.de/media/exercise-images/71/Cable-crossover-1.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Elevación lateral con mancuernas', 'Posición inicial De pie con los pies separados a la anchura de los hombros, los brazos a lo largo del cuerpo y una mancuerna en cada mano.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'elevacion-lateral-con-mancuernas', 'https://wger.de/media/exercise-images/148/lateral-dumbbell-raises-large-2.png', 'https://wger.de/media/exercise-images/148/lateral-dumbbell-raises-large-1.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Remo lateral en polea a un brazo', 'Coloca la polea a la altura de la cintura, comienza con el brazo cruzado sobre el abdomen y desplaza la mano hacia el otro lado y hacia afuera, un brazo cada vez.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'remo-lateral-en-polea-a-un-brazo', 'https://wger.de/media/exercise-images/349/9d969203-9cb6-4d47-9c31-fef53bfe1de5.png', 'https://wger.de/media/exercise-images/349/8dc5ad63-a93a-496f-9473-ac414236e58d.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Curl femoral', 'El curl de piernas, también conocido como curl de isquiotibiales, es un ejercicio de aislamiento que se enfoca en los músculos isquiotibiales. El ejercicio consiste en flexionar la parte inferior de la pierna contra la resistencia hacia las nalgas. Otros ejercicios que se pueden utilizar para fortalecer los isquiotibiales son las elevaciones de glúteos y isquiotibiales y el peso muerto.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'curl-femoral', 'https://wger.de/media/exercise-images/364/b318dde9-f5f2-489f-940a-cd864affb9e3.png', 'https://wger.de/media/exercise-images/364/b318dde9-f5f2-489f-940a-cd864affb9e3.png', 'wger.de', 'CC0', 'BFad07'),
  ('Curl de piernas (tumbado)', 'Túmbate en un banco y coloca los gemelos detrás del soporte para las piernas (mejor si quedan sujetos por la parte baja de los gemelos). Agárrate a las barras para asegurarte de que el cuerpo queda firmemente fijado. Flexiona las piernas llevando el peso hacia arriba y baja lentamente. Durante el ejercicio el cuerpo no debe moverse, todo el trabajo lo hacen las piernas.', 'accessory', 'intermediate', '[]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios"]'::jsonb, 'hamstrings', 'curl-de-piernas-tumbado', 'https://wger.de/media/exercise-images/154/lying-leg-curl-machine-large-1.png', 'https://wger.de/media/exercise-images/154/lying-leg-curl-machine-large-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Curl femoral sentado', 'Ajusta la palanca de la máquina para adaptarla a tu altura y siéntate en la máquina con la espalda contra la almohadilla de respaldo. Coloca los tobillos sobre los cojines , los muslos debajo del cojinete de sujeción justo por encima de las rodillas y las manos en los agarres.Al inspirar realiza una flexión de las rodillas. Mantener la espalda inmóvil en todo momento únicamente solo debe movilizarse los pies por la flexión de rodilla. Mantén la posición contraída por un segundo. Lentamente regresa a la posición inicial. Espirar al final del movimiento.', 'accessory', 'intermediate', '[]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios"]'::jsonb, 'hamstrings', 'curl-femoral-sentado', 'https://wger.de/media/exercise-images/117/seated-leg-curl-large-1.png', 'https://wger.de/media/exercise-images/117/seated-leg-curl-large-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Beinbeuger Stehend', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios"]'::jsonb, 'hamstrings', 'beinbeuger-stehend', 'https://wger.de/media/exercise-images/118/standing-leg-curls-large-1.png', 'https://wger.de/media/exercise-images/118/standing-leg-curls-large-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Curl cuadriceps', 'La extensión de piernas es un ejercicio de entrenamiento con pesas de resistencia que se enfoca en el músculo cuádriceps de las piernas. El ejercicio se realiza utilizando una máquina llamada Leg Extension Machine. Hay varios fabricantes de estas máquinas y cada uno es ligeramente diferente. La mayoría de los gimnasios y salas de pesas tendrán la máquina en sus instalaciones. La extensión de piernas es un ejercicio aislado dirigido a un grupo muscular específico, los cuádriceps. No debe considerarse como un entrenamiento total de piernas, como la sentadilla o el peso muerto. El ejercicio consiste en doblar la pierna a la altura de la rodilla y extender las piernas, para luego volver a bajarlas a la posición original.', 'accessory', 'intermediate', '[]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'curl-cuadriceps', 'https://wger.de/media/exercise-images/369/78c915d1-e46d-4d30-8124-65d68664c3ef.png', 'https://wger.de/media/exercise-images/369/4d621b17-f6cb-4107-97c0-9f44e9a2dbc6.webp', 'wger.de', 'CC0', 'BFad07'),
  ('Prensa de piernas', 'La prensa de piernas es un ejercicio de entrenamiento con pesas en el que el individuo empuja un peso o una resistencia con las piernas.', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gemelos","gluteos","piernas"]'::jsonb, 'hamstrings', 'prensa-de-piernas', 'https://wger.de/media/exercise-images/371/d2136f96-3a43-4d4c-9944-1919c4ca1ce1.webp', 'https://wger.de/media/exercise-images/371/d2136f96-3a43-4d4c-9944-1919c4ca1ce1.webp', 'wger.de', 'CC0', 'BFad07'),
  ('Prensa de piernas cerrada', 'El ejercicio es muy similar a la prensa de pierna ancha: Siéntese en la máquina y coloque los pies en la plataforma tan separados que podría poner otro pie entre ellos. Los pies son paralelos y apuntan hacia arriba. Baje tanto el peso, que las rodillas formen un ángulo recto. Vuelva a empujar inmediatamente la plataforma hacia arriba, sin ninguna pausa. Cuando está en la posición más baja, las rodillas apuntan un poco hacia afuera y el movimiento debe ser siempre fluido.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'prensa-de-piernas-cerrada', 'https://wger.de/media/exercise-images/373/60e2aa21-1910-40d3-9fed-babfee06dd48.png', 'https://wger.de/media/exercise-images/373/60e2aa21-1910-40d3-9fed-babfee06dd48.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Kniebeuge an Hackenschmidtmaschine', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'kniebeuge-an-hackenschmidtmaschine', 'https://wger.de/media/exercise-images/130/Narrow-stance-hack-squats-1-1024x721.png', 'https://wger.de/media/exercise-images/130/Narrow-stance-hack-squats-2-1024x721.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Elevaciones de piernas tumbado', 'Túmbate en un banco y sujétate al respaldo con las manos para mantenerte estable. Mantén las piernas rectas y elévalas hasta que formen un ángulo de unos 45°. Haz una breve pausa de 1 seg. y baja lentamente hasta la posición inicial. Para aumentar la intensidad puedes hacer una pausa más larga de 7 seg. cada 5 repeticiones.', 'core', 'intermediate', '["gym_mat"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'elevaciones-de-piernas-tumbado', 'https://wger.de/media/exercise-images/125/Leg-raises-2.png', 'https://wger.de/media/exercise-images/125/Leg-raises-1.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Remo sentado', 'Siéntate, apoya los pies en los puntos de apoyo y agarra la barra con un agarre amplio. Tire de la pesa con un movimiento rápido hacia el ombligo, no hacia arriba. Durante el movimiento, mantén los brazos y los codos pegados al cuerpo. Junta los hombros. Deja que el peso baje lentamente hasta que tus brazos estén completamente estirados.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-sentado', 'https://wger.de/media/exercise-images/394/5e0c015f-9e4c-4034-beea-b0afbf15d0bd.png', 'https://wger.de/media/exercise-images/143/Cable-seated-rows-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press militar', 'En una barra SZ, tome sus manos en el exterior de cada curva y párese con los brazos rectos hacia abajo, con las palmas hacia las piernas. Tire de la barra (doblando los brazos por el codo) hacia el pecho y empuje la barra por encima de la cabeza (los brazos lo más rectos posible). Regrese la barra a su pecho dejando caer los brazos a la altura de los codos. Regrese la barra a su posición original (párese con los brazos hacia abajo, las palmas hacia las piernas).', 'accessory', 'intermediate', '["sz-bar"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'press-militar', 'https://wger.de/media/exercise-images/418/fa2a2207-43cb-4dc0-bc2a-039e32544790.png', 'https://wger.de/media/exercise-images/418/fa2a2207-43cb-4dc0-bc2a-039e32544790.png', 'wger.de', 'CC-BY-SA 3', 'mbozi1'),
  ('Crunches negativos', 'Siéntate en el banco declinado y fija las piernas. Cruza los brazos sobre el pecho y eleva el torso con un movimiento de enrollamiento; baja ahora de nuevo sin pausa y con un movimiento lento. No dejes que la cabeza se mueva durante el ejercicio.', 'core', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'crunches-negativos', 'https://wger.de/media/exercise-images/93/Decline-crunch-1.png', 'https://wger.de/media/exercise-images/93/Decline-crunch-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Flexiones de pica', 'Posición de mirada fija: Perro mirando hacia abajo:Tu cuerpo debe hacer una forma de V, con la espalda, los brazos y las piernas rectas. Las caderas deben estar en el aire.Puedes llegar a esta posición caminando con las manos hacia atrás desde una plancha alta. Pasos: 1.Dobla los codos hacia los lados, manteniendo la espalda y las piernas rectas y acercando la cabeza al suelo. Estira los brazos, empujando las caderas hacia atrás y manteniendo la espalda y las piernas rectas. Repite la operación.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'flexiones-de-pica', 'https://wger.de/media/exercise-images/454/447f3c17-405f-46e0-b138-65c2a8caaab0.png', 'https://wger.de/media/exercise-images/454/447f3c17-405f-46e0-b138-65c2a8caaab0.png', 'wger.de', 'CC-BY-SA 4', 'Nash'),
  ('Sentadillas en pistol izquierda', 'Párese en una pierna, con la otra pierna estirada y ligeramente hacia adelante. Doble una rodilla lentamente, bajando en sentadilla y manteniendo la espalda y la otra pierna estirada. Levántese lentamente de la sentadilla, enderezando la rodilla doblada y manteniendo la otra pierna recta. Repita', 'accessory', 'intermediate', '[]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'sentadillas-en-pistol-izquierda', 'https://wger.de/media/exercise-images/456/3b681e59-377b-40db-9113-ca5873ce084b.jpg', 'https://wger.de/media/exercise-images/456/c51d875b-0c07-495e-a7cf-08893a9f125d.jpg', 'wger.de', 'CC-BY-SA 3', 'minifigmaster125'),
  ('Plancha de antebrazo', 'Posición de salida: Empiece a cuatro patas.Los brazos deben estar doblados en ángulo recto, con los hombros justo sobre los codos.La espalda debe estar recta, todo el cuerpo en línea recta. Pasos: Mantenga esta posición.', 'core', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'plancha-de-antebrazo', 'https://wger.de/media/exercise-images/458/b7bd9c28-9f1d-4647-bd17-ab6a3adf5770.png', 'https://wger.de/media/exercise-images/458/902e6836-394e-458b-b94e-101d714294e2.png', 'wger.de', 'CC-BY-SA 3', 'YYCfit / BFad07'),
  ('Curl en banco Scott', 'Coloca la barra Z sobre los soportes situados delante del banco Scott. Inclínate sobre el banco y agarra la barra Z con las palmas hacia arriba. Siéntate en el asiento del banco Scott de modo que la parte superior de los brazos descanse sobre la almohadilla y el pecho quede apoyado contra ella. Baja el peso hasta que los codos queden extendidos y los brazos rectos. Vuelve a subir los pesos hasta el punto inicial contrayendo los bíceps. Repite.', 'accessory', 'intermediate', '["sz-bar"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-en-banco-scott', 'https://wger.de/media/exercise-images/193/Preacher-curl-3-1.png', 'https://wger.de/media/exercise-images/193/Preacher-curl-3-2.png', 'wger.de', 'CC-BY-SA 3', 'cgoob883'),
  ('Dominadas', 'Toma la barra con los brazos a la altura de los hombros y las palmas de las manos hacia el frente. Intenta sacar el pecho, apretar el abdomen y tirar con las dorsales para elevarte hacia arriba hasta sobrepasar la barra con la barbilla intentando mantener el resto del cuerpo completamente estático', 'accessory', 'intermediate', '["pull-up_bar"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'dominadas', 'https://wger.de/media/exercise-images/475/b0554016-16fd-4dbe-be47-a2a17d16ae0e.jpg', 'https://wger.de/media/exercise-images/475/b0554016-16fd-4dbe-be47-a2a17d16ae0e.jpg', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press de hombro con mancuernas', 'El press de hombro con mancuernas es un ejercicio fundamental para fortalecer los deltoides, tríceps y músculos estabilizadores, que se puede realizar sentado o de pie, implicando empujar mancuernas desde la altura de los hombros hasta la extensión casi completa de los brazos, manteniendo la espalda recta y los codos ligeramente hacia adelante para proteger el manguito rotador, y bajando de forma controlada', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["deltoids"]'::jsonb, 'deltoids', 'press-de-hombro-con-mancuernas', 'https://wger.de/media/exercise-images/478/70a2d72c-a822-45f3-8de2-54ea85951b84.jpg', 'https://wger.de/media/exercise-images/478/70a2d72c-a822-45f3-8de2-54ea85951b84.jpg', 'wger.de', 'CC-BY-SA 3', 'sistab2'),
  ('Peso muerto en rack', 'Peso muerto que se realiza con una máquina Smith o un rack libre. La barra debe quedar justo por debajo del nivel de la rótula. Levanta con los glúteos y a través de los talones, y luego vuelve a la posición inicial con un movimiento controlado de 2 segundos. Este ejercicio trabaja principalmente la zona lumbar y los glúteos.', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lower_back","gluteos"]'::jsonb, 'lower_back', 'peso-muerto-en-rack', 'https://wger.de/media/exercise-images/161/Dead-lifts-2.png', 'https://wger.de/media/exercise-images/161/Dead-lifts-1.png', 'wger.de', 'CC-BY-SA 3', 'Mahoney'),
  ('Elevaciones de deltoides posterior', 'Sentado en un banco con las mancuernas en el suelo, inclínate 45 grados hacia delante y luego eleva lentamente cada mancuerna hasta la altura de los hombros, manteniéndola un par de segundos antes de bajarla a la posición inicial.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids"]'::jsonb, 'deltoids', 'elevaciones-de-deltoides-posterior', 'https://wger.de/media/exercise-images/487/ad724e5c-b1ed-49e8-9279-a17545b0dd0b.png', 'https://wger.de/media/exercise-images/487/692c598c-0493-42a5-be8b-b9d2e9adcd00.png', 'wger.de', 'CC-BY-SA 3', 'YYCfit'),
  ('Peso muerto rumano con barra', 'De pie con los pies separados a la anchura de los hombros y los dedos de los pies mirando hacia adelante. Dobla las rodillas ligeramente y empuja el pecho hacia afuera. Agarra una barra que descanse en la parte superior de los muslos, con las manos en pronación a la anchura de los hombros.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'peso-muerto-rumano-con-barra', 'https://wger.de/media/exercise-images/507/13d526ab-12fc-461e-828a-051dd7c13fb1.png', 'https://wger.de/media/exercise-images/507/13d526ab-12fc-461e-828a-051dd7c13fb1.png', 'wger.de', 'CC-BY-SA 4', 'pjwirth'),
  ('Remo Gironda', 'Coloca la polea en el peldaño más bajo de la máquina. Coloque los pies en los soportes disponibles, si no hay soporte, busca un step y colócalo delante de la máquina antes de colocar los pies en ella. Comienza con los brazos completamente extendidos, ya que este movimiento se dirige a los dorsales y esta posición es la que mejor compromete la zona. Mantén la cabeza, la espalda y la columna vertebral alineadas de forma neutra, con el pecho elevado y el núcleo comprometido. Con una pequeña flexión de las rodillas, tira del accesorio hacia tu cuerpo hasta justo debajo del ombligo, iniciando el movimiento llevando los codos hacia las caderas, manteniendo los codos dentro. Cuando el agarre (accesorio) llegue a tu torso, aprieta los dorsales y los omóplatos, manteniendo la contracción durante 1-', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-gironda', 'https://wger.de/media/exercise-images/512/b938437e-ff00-4679-9036-acb41bb28bbd.png', 'https://wger.de/media/exercise-images/512/b938437e-ff00-4679-9036-acb41bb28bbd.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Remo en "T"', 'La ejecución de este ejercicio es muy similar a la del remo inclinado normal, solo que aquí la barra está fija. Agarra la barra con un agarre amplio (ligeramente más ancho que los hombros) e inclínate hacia delante. La parte superior del cuerpo no debe quedar totalmente paralela al suelo, sino formar un ligero ángulo. Mantén el pecho hacia fuera durante todo el ejercicio. Tira de la barra con un movimiento rápido hacia el ombligo, sin subirla más. Vuelve lentamente a la posición inicial. No balancees el cuerpo y mantén los brazos pegados al cuerpo.', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-en-t', 'https://wger.de/media/exercise-images/106/T-bar-row-1.png', 'https://wger.de/media/exercise-images/106/T-bar-row-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press inclinado con mancuernas', 'Es una variante del press plano orientada a enfatizar el trabajo en el haz clavicular del pectoral (la sección superior). Al inclinar el torso, el ángulo de empuje cambia, transfiriendo más tensión hacia la parte alta del pecho y los hombros, lo que ayuda a conseguir un desarrollo más estético, equilibrado y tridimensional del torso. Ajuste del banco y preparación: Coloca el banco a una inclinación de entre 30 y 45 grados (una inclinación mayor a 45° pasará demasiado esfuerzo al hombro y restará estímulo al pecho). Siéntate con una mancuerna sobre cada muslo. Posición de inicio: Túmbate hacia atrás apoyando la espalda en el respaldo, mientras usas las rodillas secuencialmente para impulsar las mancuernas hacia arriba, a la altura de tus hombros. Estabilización anatómica: Planta los pies fi', 'accessory', 'intermediate', '["dumbbell","incline_bench"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'press-inclinado-con-mancuernas', 'https://wger.de/media/exercise-images/16/Incline-press-1.png', 'https://wger.de/media/exercise-images/537/9f3c7817-3e3d-417d-8b08-2c0a1aa5fe03.jpg', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press de banca inclinado', 'Press de banca inclinado con barra fija.', 'accessory', 'intermediate', '["barbell","incline_bench"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'press-de-banca-inclinado', 'https://wger.de/media/exercise-images/41/Incline-bench-press-1.png', 'https://wger.de/media/exercise-images/41/Incline-bench-press-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Distensione su Panca Piana Imp Stretta', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'distensione-su-panca-piana-imp-stretta', 'https://wger.de/media/exercise-images/61/Close-grip-bench-press-1.png', 'https://wger.de/media/exercise-images/61/Close-grip-bench-press-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press de hombro con maquina', 'Sentarse en la máquina con las piernas separadas a la anchura de los hombros. Mantener la espalda erguida y también los brazos flexionados para tomar la barra a la altura de los hombro, alzar la barra lo mas alto que se pueda con los brazos extendidos. Bajar lentamente y repetir.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'press-de-hombro-con-maquina', 'https://wger.de/media/exercise-images/53/Shoulder-press-machine-2.png', 'https://wger.de/media/exercise-images/53/Shoulder-press-machine-1.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press de hombros con barra', 'Siéntate en un banco; el respaldo debe estar casi vertical. Coge una barra con un agarre del ancho de los hombros y súbela hasta la altura del pecho. Empuja el peso hacia arriba, pero no estires los brazos por completo. Baja lentamente y repite.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'press-de-hombros-con-barra', 'https://wger.de/media/exercise-images/119/seated-barbell-shoulder-press-large-1.png', 'https://wger.de/media/exercise-images/119/seated-barbell-shoulder-press-large-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Press Militar mancuerna', 'Siéntate en un banco, con el respaldo casi vertical. Toma dos mancuernas y súbelas a la altura de los hombros, con las palmas y los codos apuntando hacia adelante durante todo el ejercicio. Empuja las mancuernas hacia arriba; en el punto más alto, se acercarán mucho, pero sin tocarse. Baja lentamente y repite.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'press-militar-mancuerna', 'https://wger.de/media/exercise-images/123/dumbbell-shoulder-press-large-1.png', 'https://wger.de/media/exercise-images/123/dumbbell-shoulder-press-large-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Encogimiento de hombros', 'El encogimiento de hombros (normalmente llamado simplemente encogimiento) es un ejercicio de entrenamiento con pesas usado para desarrollar el trapecio superior. Quien levanta el peso se mantiene erguido, con las manos aproximadamente al ancho de los hombros, eleva los hombros lo más alto posible y luego los baja, sin flexionar los codos ni mover el cuerpo en absoluto. Es posible que no se tenga un rango de movimiento tan amplio como en un encogimiento normal realizado para flexibilidad activa. Suele considerarse buena técnica si la línea de los hombros queda horizontal en la posición elevada.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["deltoids"]'::jsonb, 'deltoids', 'encogimiento-de-hombros', 'https://wger.de/media/exercise-images/570/68b4a33f-40f1-4dda-b56c-a2e20ed13903.jpg', 'https://wger.de/media/exercise-images/570/68b4a33f-40f1-4dda-b56c-a2e20ed13903.jpg', 'wger.de', 'CC0', 'BFad07'),
  ('Encogimientos de hombros con barra', 'Coge una barra y ponte de pie con el cuerpo erguido; los brazos cuelgan libremente delante de ti. Desde esta posición, eleva los hombros lo más alto que puedas, pero no flexiones los brazos durante el movimiento. En el punto más alto, haz una breve pausa de 1 o 2 segundos antes de volver lentamente a la posición inicial. Cuando entrenes con un peso mayor, asegúrate de seguir realizando el movimiento completo.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'encogimientos-de-hombros-con-barra', 'https://wger.de/media/exercise-images/150/Barbell-shrugs-1.png', 'https://wger.de/media/exercise-images/150/Barbell-shrugs-2.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Encogimientos de hombros con mancuernas', 'Ponte de pie con el cuerpo erguido; las manos cuelgan libremente a los lados, cada una sujetando una mancuerna. Desde esta posición, eleva los hombros lo más alto que puedas, pero no flexiones los brazos durante el movimiento. En el punto más alto, haz una breve pausa de 1 o 2 segundos antes de volver lentamente a la posición inicial. Cuando entrenes con un peso mayor, asegúrate de seguir realizando el movimiento completo.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'encogimientos-de-hombros-con-mancuernas', 'https://wger.de/media/exercise-images/151/Dumbbell-shrugs-2.png', 'https://wger.de/media/exercise-images/572/9e730259-1dcd-4b5e-b4cc-9ebc0cfda75c.webp', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Side Crunch', 'Ejercicio de entrenamiento guiado.', 'core', 'intermediate', '["gym_mat"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'side-crunch', 'https://wger.de/media/exercise-images/176/Cross-body-crunch-1.png', 'https://wger.de/media/exercise-images/176/Cross-body-crunch-2.png', 'wger.de', 'CC-BY-SA 3', 'kwrindy'),
  ('Elevación de talón de pie', 'Mire hacia la máquina y coloque las puntas de los pies en el borde más cercano del escalón con los pies paralelos entre sí. Sumerja su cuerpo debajo de las hombreras y póngase de pie con el cuerpo completamente erguido. Permita que sus talones caigan más abajo que el escalón hasta que sienta un estiramiento. No permita que le bloqueen las rodillas. Movimiento hacia arriba Ponga los dedos de los pies en punta para levantar los talones arriba. Mantenga su cuerpo erguido y no mire hacia abajo ni se incline hacia adelante o hacia atrás. Movimiento descendente Permita que sus talones vuelvan a caer a la posición inicial. Mantenga su cuerpo completamente erguido y no rebote desde la posición más baja para comenzar el movimiento ascendente.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'elevacion-de-talon-de-pie', 'https://wger.de/media/exercise-images/622/9a429bd0-afd3-4ad0-8043-e9beec901c81.jpeg', 'https://wger.de/media/exercise-images/622/d6d57067-97de-462e-a8bb-15228d730323.jpeg', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Peso muerto sumo', 'Comienza con una barra cargada en el suelo. Acércate a la barra de modo que esta cruce la mitad de los pies. Los pies deben colocarse muy separados, cerca de los discos. Flexiona las caderas para agarrar la barra. Los brazos deben quedar directamente debajo de los hombros, por dentro de las piernas, y puedes usar un agarre prono, un agarre mixto o un agarre de gancho. Relaja los hombros, lo que en efecto alarga los brazos. Toma aire y luego baja las caderas, mirando al frente con la cabeza y el pecho hacia arriba. Empuja contra el suelo, separando los pies, con el peso en la mitad trasera de los pies. Extiende las caderas y las rodillas. Cuando la barra pase las rodillas, échate hacia atrás y lleva las caderas hacia la barra, juntando los omóplatos. Devuelve el peso al suelo flexionando la', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos","piernas"]'::jsonb, 'hamstrings', 'peso-muerto-sumo', 'https://wger.de/media/exercise-images/630/b0f0c7d8-5878-4d9e-b820-21acc013741d.webp', 'https://wger.de/media/exercise-images/630/b0f0c7d8-5878-4d9e-b820-21acc013741d.webp', 'wger.de', 'CC-BY-SA 4', 'magdy'),
  ('Extension de triceps polea', 'Coge el cable, párate con los pies a la altura de los hombros, mantén la espalda recta e inclínate un poco hacia delante. Empuje la barra hacia abajo, asegurándose de que los codos no se muevan durante el ejercicio. Gire las manos hacia afuera al final y vuelva a la posición inicial sin pausa.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'extension-de-triceps-polea', 'https://wger.de/media/exercise-images/659/a60452f1-e2ea-43fe-baa6-c1a2208d060c.png', 'https://wger.de/media/exercise-images/659/a60452f1-e2ea-43fe-baa6-c1a2208d060c.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Remo al mentón en multipower', 'Los movimientos son básicamente los mismos que con una barra SZ, pero usas la barra del multipower: Ponte de pie erguido, con los pies separados al ancho de los hombros. Sujeta la barra con un agarre prono a la altura de los muslos, con los brazos estirados. Sube la barra cerca del cuerpo hasta el mentón. Los codos apuntan hacia fuera, de modo que en el punto más alto forman una V. Haz aquí una breve pausa antes de bajar lentamente y repetir el movimiento.', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'remo-al-menton-en-multipower', 'https://wger.de/media/exercise-images/691/297d4ce1-7e9e-4adb-8f5c-7d54054be885.jpg', 'https://wger.de/media/exercise-images/691/72bb8231-8994-453f-8a3f-85b061dcffb8.jpg', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Remo al Menton', 'Separamos las piernas a la distancia de los hombros. Cogemos la barra con agarre Prono, siendo el agarre ancho a la altura de los hombros por lo menos.(explicaremos en los errores comunes el porque de este agarre). Elevamos la barra hacia el mentón pero sin llegar a tocarlo, aguantamos 1 segundo y volvemos a bajar de forma controlada. La espalda siempre recta y sin ningún tipo de balanceo corporal.', 'accessory', 'intermediate', '["sz-bar"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'remo-al-menton', 'https://wger.de/media/exercise-images/693/05c91bd2-7814-40b6-b2d1-51ae942b8321.png', 'https://wger.de/media/exercise-images/693/05c91bd2-7814-40b6-b2d1-51ae942b8321.png', 'wger.de', 'CC-BY-SA 3', 'wger.de'),
  ('Remo al mentón con mancuernas', 'Sujeta una mancuerna en cada mano delante del cuerpo. Mantén las palmas hacia el cuerpo. Sube las manos en línea recta hasta que queden bajo el mentón, y luego bájalas. Repite el ejercicio.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'remo-al-menton-con-mancuernas', 'https://wger.de/media/exercise-images/694/119e6823-6960-4341-a9e1-aaf78d7fb57c.png', 'https://wger.de/media/exercise-images/694/2e69c005-b241-4806-8557-fc5a4d5ee44d.png', 'wger.de', 'CC-BY-SA 4', 'koreyhinton'),
  ('Suspensión en Romos', 'Este es un ejercicio avanzado específico de escalada, diseñado para fortalecer el agarre de mano abierta y la tensión corporal en presas redondeadas o inclinadas que no tienen un borde definido. Para realizarlo, cuélgate de los agarres romos (slopers) de una tabla de multipresas. La técnica es crucial: mantén los hombros activos (lejos de las orejas) y los codos ligeramente flexionados para proteger las articulaciones. A diferencia de otros agarres, en los romos es vital usar la mano lo más abierta posible para maximizar la superficie de contacto y la fricción. Contrae el core para mantener el cuerpo estable y sostén la posición durante los segundos indicados en tu rutina.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'suspension-en-romos', 'https://wger.de/media/exercise-images/804/6f4b8bd9-fa05-49de-870b-1f79b595ce89.png', 'https://wger.de/media/exercise-images/804/6f4b8bd9-fa05-49de-870b-1f79b595ce89.png', 'wger.de', 'CC-BY-SA 4', 'marcelbader'),
  ('Empuje de tríceps en cable', 'El empuje hacia abajo de la cuerda del cable es un ejercicio popular dirigido a los músculos tríceps. Es fácil de aprender y realizar, lo que lo convierte en el favorito de todos, desde principiantes hasta levantadores avanzados. Por lo general, se realiza para repeticiones de moderadas a altas, como 8-12 repeticiones o más por serie, como parte de un entrenamiento centrado en la parte superior del cuerpo o en los brazos.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'empuje-de-triceps-en-cable', 'https://wger.de/media/exercise-images/805/7a437824-e2cc-46e1-804a-674f0ea31d25.png', 'https://wger.de/media/exercise-images/805/7a437824-e2cc-46e1-804a-674f0ea31d25.png', 'wger.de', 'CC-BY-SA 4', 'cshep442'),
  ('Aperturas Posteriores en Polea', 'Ajusta el peso y sitúa las poleas en una posición alta, por encima de tu cabeza. Con la mano derecha, agarra el mango de la polea izquierda, y con la mano izquierda, el de la polea derecha, cruzando los cables frente a ti. Esta es tu posición de inicio. Comienza el movimiento abriendo los brazos hacia los lados y hacia atrás en un arco amplio, manteniendo una ligera flexión en los codos. Haz una breve pausa al final del movimiento para contraer al máximo los músculos de la espalda, antes de regresar los mangos a la posición inicial de forma controlada.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'aperturas-posteriores-en-polea', 'https://wger.de/media/exercise-images/822/74affc0d-03b6-4f33-b5f4-a822a2615f68.png', 'https://wger.de/media/exercise-images/822/6a770e5d-cd62-4754-a18c-eebe2103d7c5.png', 'wger.de', 'CC-BY-SA 4', 'cshep442'),
  ('Aperturas Inversas', 'Los "pájaros" con mancuernas en banco inclinado son un ejercicio del tren superior que se enfoca en los deltoides posteriores, así como en los músculos posturales de la espalda alta. Para ejecutarlo, debes acostarte boca abajo sobre el banco inclinado, con el pecho firmemente apoyado. Debido a que trabaja músculos relativamente pequeños, este ejercicio se suele realizar con un peso ligero a cambio de un número alto de repeticiones, como series de 10 a 15 repeticiones o más.', 'accessory', 'intermediate', '["dumbbell","incline_bench"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'aperturas-inversas', 'https://wger.de/media/exercise-images/828/2e959dab-f39b-4c7c-9063-eb43064ab5eb.png', 'https://wger.de/media/exercise-images/828/abfc7700-fadf-4f2d-ac84-e045e590a2fe.png', 'wger.de', 'CC-BY-SA 4', 'cshep442'),
  ('Curl Nórdico Inverso', 'Arrodíllate con los tobillos asegurados por un compañero o un objeto fijo. Manteniendo una línea recta desde las rodillas hasta la cabeza, inclínate lentamente hacia atrás, controlando el movimiento con tus cuádriceps. Usa la misma fuerza para volver a la posición inicial. Es una alternativa muy efectiva a la máquina de extensión de piernas.', 'accessory', 'intermediate', '[]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'curl-nordico-inverso', 'https://wger.de/media/exercise-images/909/159222d9-c1e4-46ae-89ee-6a2dfaab978d.png', 'https://wger.de/media/exercise-images/909/159222d9-c1e4-46ae-89ee-6a2dfaab978d.png', 'wger.de', 'CC-BY-SA 4', 'karly'),
  ('Curl en Polea con Barra Recta', 'De pie frente a una polea baja, toma la barra recta con las palmas hacia arriba. Manteniendo los codos fijos a los costados de tu cuerpo, flexiónalos para subir la barra y contraer fuertemente los bíceps. Baja de manera controlada para mantener la tensión constante del cable.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-en-polea-con-barra-recta', 'https://wger.de/media/exercise-images/912/e10a034f-6370-4dd6-b1c2-416b27844529.png', 'https://wger.de/media/exercise-images/912/e10a034f-6370-4dd6-b1c2-416b27844529.png', 'wger.de', 'CC-BY-SA 4', 'novadani'),
  ('Volante', 'Este ejercicio, que simula el movimiento de girar el volante de un autobús, es excelente para trabajar la resistencia y la fuerza de rotación del core, además de los deltoides. Instrucciones Posición: Siéntate en el suelo o en un banco, manteniendo la espalda recta y el abdomen contraído. Sostén un disco (placa) con ambas manos frente a ti, a la altura del pecho o los hombros, como si fuera un volante. Movimiento: Gira el disco de un lado a otro de forma controlada, rotando desde el torso. Imagina que estás conduciendo un autobús y girando el volante en curvas pronunciadas. Control: El movimiento debe originarse en tu core, no solo en tus brazos. Mantén los brazos relativamente extendidos durante todo el ejercicio. (Para mayor dificultad, realízalo sentado en el suelo con los pies elevados', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'volante', 'https://wger.de/media/exercise-images/915/fe8ebece-dff8-4700-b84c-9110e2e074f5.png', 'https://wger.de/media/exercise-images/915/fe8ebece-dff8-4700-b84c-9110e2e074f5.png', 'wger.de', 'CC-BY-SA 4', 'novadani'),
  ('Prensa Smith', 'Sentado en un ángulo de casi 90 grados, máquina Smith', 'accessory', 'intermediate', '["incline_bench"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'prensa-smith', 'https://wger.de/media/exercise-images/916/9bf7555a-fec6-43a9-b343-aae496744e5e.png', 'https://wger.de/media/exercise-images/916/9bf7555a-fec6-43a9-b343-aae496744e5e.png', 'wger.de', 'CC-BY-SA 4', 'novadani'),
  ('Press Inclinado Ligero en Máquina Smith', 'Esta variante con una inclinación muy leve (aproximadamente 15-30 grados) es excelente para enfocar el trabajo en la parte superior del pectoral y la sección clavicular del deltoide, con la estabilidad que ofrece la máquina Smith. Instrucciones: Coloca un banco ajustable debajo de la barra de la máquina Smith y ajústalo a un ángulo de inclinación bajo (uno o dos puntos por encima de la posición plana). Sujeta la barra con un agarre ligeramente más ancho que tus hombros. Baja la barra de forma controlada hasta la parte alta de tu pecho, y luego empújala explosivamente hacia arriba hasta la posición inicial, contrayendo los pectorales superiores.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'press-inclinado-ligero-en-maquina-smith', 'https://wger.de/media/exercise-images/925/67dbb1c9-b378-46f9-adb6-1f55b3d3007a.png', 'https://wger.de/media/exercise-images/925/67dbb1c9-b378-46f9-adb6-1f55b3d3007a.png', 'wger.de', 'CC-BY-SA 4', 'novadani'),
  ('Aperturas en Máquina para Pecho', 'Este es un ejercicio de aislamiento excelente para enfocar el trabajo en la contracción de los músculos pectorales, especialmente en la parte interna del pecho. Instrucciones Posición: Siéntate en la máquina con la espalda firmemente apoyada en el respaldo. Ajusta la altura del asiento para que tus hombros, codos y manos queden al mismo nivel (los brazos paralelos al suelo). Movimiento: Con una ligera flexión constante en los codos, junta los agarres al frente en un movimiento de arco, como si dieras un gran abrazo. Contracción: Aprieta con fuerza los músculos del pecho en el punto de máxima contracción. Regresa a la posición inicial de forma lenta y controlada, sin dejar que las placas de peso choquen.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'aperturas-en-maquina-para-pecho', 'https://wger.de/media/exercise-images/926/ae9deb5d-a1e9-4c30-b1e3-c128ba5d4969.png', 'https://wger.de/media/exercise-images/926/ae9deb5d-a1e9-4c30-b1e3-c128ba5d4969.png', 'wger.de', 'CC-BY-SA 4', 'novadani'),
  ('flexiones en TRX', 'Las flexiones de brazos en TRX añaden un componente de inestabilidad que hará que tus hombros y tus pectorales trabajen de manera diferente. Puedes hacer que el ejercicio sea más o menos intenso colocando tu cuerpo más paralelo o menos al suelo. Evita que tus brazos rocen con las cuerdas porque puede que no lo notes mientras entrenas, pero podrás tener rozaduras y moratones después.', 'cardio', 'beginner', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'flexiones-en-trx', 'https://wger.de/media/exercise-images/927/7b392101-9c47-4693-935e-a88b1887eec5.jpg', 'https://wger.de/media/exercise-images/927/7b392101-9c47-4693-935e-a88b1887eec5.jpg', 'wger.de', 'CC-BY-SA 4', ''),
  ('Elevación de brazo y pierna en cuadrupedia', 'En este ejercicio se activan los músculos de la espalda y los músculos de la parte posterior de la pierna y del brazo al levantar al mismo tiempo el brazo y la pierna cruzados en posición de cuadrupedia. También mejora el equilibrio y la propiocepción. El movimiento se realiza de forma simétrica. Colócate en posición de cuadrupedia.2. Mete el abdomen y luego levanta tu pierna derecha y tu brazo izquierdo.3. Debes mantener el abdomen metido durante 8 segundos.4. Después de 8 segundos, baja lentamente el brazo y la pierna.5. Luego relaja los músculos.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros","gluteos"]'::jsonb, 'deltoids', 'elevacion-de-brazo-y-pierna-en-cuadrupedia', 'https://wger.de/media/exercise-images/957/0fd94587-6021-4763-856e-7227f5fcba2a.png', 'https://wger.de/media/exercise-images/957/0fd94587-6021-4763-856e-7227f5fcba2a.png', 'wger.de', 'CC-BY-SA 4', 'utkb'),
  ('Biceps con TRX', 'músculos implicados: bíceps Agarre las asas de las correas TRX, incline el cuerpo hacia atrás, brazos y piernas extendidos, cuerpo posicionado en una sola línea. (no es de abdominales, es de brazos)', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'biceps-con-trx', 'https://wger.de/media/exercise-images/958/947ac249-475d-44ed-bed3-8dc433374f59.png', 'https://wger.de/media/exercise-images/958/95f2bbc4-2f95-476d-a9b8-81b333fe2ef5.png', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Remo en TRX', 'Ejercicio clave para construir la fuerza necesaria para las dominadas (pull-ups). Sujeta las agarraderas del TRX e inclínate hacia atrás, manteniendo el cuerpo en una línea recta. Desde ahí, jala tu pecho hacia tus manos, contrayendo fuertemente los músculos de la espalda. La dificultad del ejercicio se ajusta con el ángulo de tu cuerpo: mientras más horizontal estés, más difícil será.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["biceps","hombros","espalda"]'::jsonb, 'biceps', 'remo-en-trx', 'https://wger.de/media/exercise-images/959/53a5e008-bc31-4ee0-9463-69a858c2ec18.png', 'https://wger.de/media/exercise-images/959/53a5e008-bc31-4ee0-9463-69a858c2ec18.png', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Swing con Kettlebell', 'Este es un ejercicio balístico fundamental que se basa en un movimiento de bisagra de cadera (hip hinge), no en una sentadilla. El poder para elevar la kettlebell no viene de los brazos, sino de un empuje explosivo de la cadera hacia adelante, manteniendo la espalda recta en todo momento. Aunque el swing con kettlebell es un ejercicio de cuerpo completo, se enfoca mayormente en los músculos de la cadena posterior (la parte trasera del cuerpo). Los principales músculos trabajados son los glúteos, los isquiotibiales, los erectores de la columna y la musculatura de la espalda alta', 'accessory', 'intermediate', '["kettlebell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lower_back","hombros","gluteos"]'::jsonb, 'lower_back', 'swing-con-kettlebell', 'https://wger.de/media/exercise-images/960/da4d0560-da89-4bb5-b91f-746458fb04ad.png', 'https://wger.de/media/exercise-images/960/da4d0560-da89-4bb5-b91f-746458fb04ad.png', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Curl de Bíceps con Kettlebell a una Mano', 'De pie, sostén una kettlebell en una mano con el brazo totalmente extendido. Comienza el movimiento flexionando el codo y levantando la pesa hasta que tu mano alcance la altura del hombro, contrayendo fuertemente el bíceps. Para realizar el ejercicio correctamente, evita impulsarte con la espalda o balancear el cuerpo; el codo debe permanecer relativamente fijo a un costado de tu torso. El movimiento debe ser controlado, enfocándose únicamente en la fuerza del brazo.', 'accessory', 'intermediate', '["kettlebell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-de-biceps-con-kettlebell-a-una-mano', 'https://wger.de/media/exercise-images/975/41d9267a-99bc-4e94-b1c4-0e39fe7a968f.png', 'https://wger.de/media/exercise-images/975/41d9267a-99bc-4e94-b1c4-0e39fe7a968f.png', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Abdominales en V con Balón Medicinal', 'Este es un ejercicio abdominal avanzado. Al usar un balón medicinal como sobrecarga, se aumenta significativamente la intensidad y la dificultad del movimiento en comparación con la versión sin peso. Para realizarlo, acuéstate boca arriba con las piernas rectas y los brazos extendidos por encima de tu cabeza, sosteniendo el balón con ambas manos. Contrayendo el abdomen, levanta simultáneamente las piernas y el torso del suelo, buscando tocar el balón con los pies en el punto más alto y formando una "V" con tu cuerpo. Baja de forma lenta y controlada a la posición inicial.', 'core', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'abdominales-en-v-con-balon-medicinal', 'https://wger.de/media/exercise-images/976/94649ea6-bf58-4fd9-90c1-b2ec96ee20cd.png', 'https://wger.de/media/exercise-images/976/94649ea6-bf58-4fd9-90c1-b2ec96ee20cd.png', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Sentadilla al Cajón', 'Este ejercicio es una variante de la sentadilla tradicional que ayuda a mejorar la técnica, desarrollar potencia y asegurar que se alcanza la profundidad correcta en el movimiento. Instrucciones: Prepara el cajón: Colócalo detrás de ti. Si vas a usar una barra, posiciona el cajón dentro de la jaula de sentadillas. Elige una altura que te permita bajar hasta que tus glúteos toquen suavemente el cajón, manteniendo la espalda recta (generalmente, con los muslos paralelos al suelo). Adopta la postura correcta: Párate frente al cajón con los pies separados al ancho de los hombros y las puntas ligeramente hacia afuera. Activa el core y mantén la espalda en una posición neutral. Si usas barra, apóyala firmemente sobre la parte alta de tu espalda. Baja de forma controlada: Inicia el movimiento emp', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'sentadilla-al-cajon', 'https://wger.de/media/exercise-images/977/3124c091-6395-4377-96c5-56048b627ceb.png', 'https://wger.de/media/exercise-images/977/3124c091-6395-4377-96c5-56048b627ceb.png', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Elevaciones de Rodillas en Barra', 'Este es un ejercicio fundamental para fortalecer la pared abdominal, con un gran enfoque en la sección inferior. Para realizarlo, cuélgate de una barra con los brazos extendidos y, sin balancearte, utiliza la fuerza de tu abdomen para elevar las rodillas hacia el pecho. El descenso debe ser lento y controlado. Una vez dominado, puedes progresar a la elevación de piernas a 90° . Como mencionas, esta es una versión mucho más intensa que involucra toda la musculatura abdominal. En lugar de flexionar las rodillas, se levantan las piernas completamente rectas hasta que quedan paralelas al suelo, formando un ángulo de 90 grados con el torso.', 'core', 'intermediate', '["pull-up_bar"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'elevaciones-de-rodillas-en-barra', 'https://wger.de/media/exercise-images/978/d3ffe51f-7eb8-4cc9-9eae-105847af3005.png', 'https://wger.de/media/exercise-images/978/d3ffe51f-7eb8-4cc9-9eae-105847af3005.png', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Elevaciones de Piernas en Barra', 'Colgado de una barra y manteniendo el cuerpo estable (sin balanceo), eleva las piernas completamente rectas hasta que formen un ángulo de 90° con tu torso. Sostén la contracción un instante y luego baja de forma lenta y controlada para maximizar el trabajo en el abdomen.', 'core', 'intermediate', '["pull-up_bar"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'elevaciones-de-piernas-en-barra', 'https://wger.de/media/exercise-images/979/27097a3a-5749-428d-b94c-6082afe390f6.png', 'https://wger.de/media/exercise-images/979/27097a3a-5749-428d-b94c-6082afe390f6.png', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Subida a peldaño', 'Párese frente a una silla Súbase a la silla Bájese de la silla Repita', 'accessory', 'intermediate', '["bench"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'subida-a-peldano', 'https://wger.de/media/exercise-images/981/f9377a7e-eb58-4cca-b805-2d36863aeb03.png', 'https://wger.de/media/exercise-images/981/f9377a7e-eb58-4cca-b805-2d36863aeb03.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Rodillas elevadas', 'Trote en el lugar, con las rodillas tan altas como pueda y cambie de pierna a un ritmo rápido', 'cardio', 'beginner', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'rodillas-elevadas', 'https://wger.de/media/exercise-images/983/16245344-9957-4a24-8d61-f9939ed5f964.png', 'https://wger.de/media/exercise-images/983/16245344-9957-4a24-8d61-f9939ed5f964.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Zancadas con peso', 'Párese con la espalda recta Dé un gran paso adelante con su pierna izquierda Baje la pelvis hasta que casi toque el suelo con la rodilla derecha Vuelva a subir la pelvis Vuelva a la posición con el pie hacia atrás Repita, cambiando de pierna cada vez', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'zancadas-con-peso', 'https://wger.de/media/exercise-images/984/5c7ffe68-e7b2-47f3-a22a-f9cc28640432.png', 'https://wger.de/media/exercise-images/984/5c7ffe68-e7b2-47f3-a22a-f9cc28640432.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Sentadilla búlgara izquierda', 'Póngase de pie delante de una silla y dé un largo paso. Ponga la parte superior de uno de sus pies en la silla Doble la rodilla delantera, balanceando los brazos hasta que la rodilla trasera casi toque el suelo. Empuje hacia atrás a la posición inicial y repita.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'sentadilla-bulgara-izquierda', 'https://wger.de/media/exercise-images/988/6283b258-a4d7-4833-84f7-a38987022d3d.png', 'https://wger.de/media/exercise-images/988/6283b258-a4d7-4833-84f7-a38987022d3d.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Patada de rodilla', 'Ponga a cuatro patas Empuje un pie hacia atrás hasta que se extienda completamente, concentrándose en los músculos de los glúteos Quédese un segundo, y luego vuelva a la posición inicial Repita, alternando los pies', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["glutes","gluteos"]'::jsonb, 'glutes', 'patada-de-rodilla', 'https://wger.de/media/exercise-images/990/de20457c-914a-45c9-8cf9-0ad9739759a1.png', 'https://wger.de/media/exercise-images/990/de20457c-914a-45c9-8cf9-0ad9739759a1.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Arremetidas inversas', 'Posición inicial: De pie, con los pies separados a la altura de las caderas. Pasos: Da un paso hacia atrás con una pierna para que pueda doblarse cómodamente hasta un ángulo de 90 grados. Doble lentamente ambas rodillas hasta formar un ángulo de 90 grados. Vuelva a la posición inicial. Repita, alternando las piernas.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'arremetidas-inversas', 'https://wger.de/media/exercise-images/999/d0931eb3-8db0-4049-bb08-aa4036072056.jfif', 'https://wger.de/media/exercise-images/999/8548b2d2-004d-48b4-95fd-b1b25f4e53d0.jfif', 'wger.de', 'CC-BY-SA 4', ''),
  ('Fondos', 'Posición inicial: Siéntate con los brazos detrás de ti, apoyando la espalda.Los dedos deben apuntar hacia adelante.Las rodillas deben estar dobladas y los pies juntos. Pasos: Levanta las caderas del suelo, estirando los brazos. Dobla los codos, llevando las caderas hacia abajo. Endereza los brazos, volviendo a la posición anterior. Repita los pasos 2 y 3. Notas: La dificultad del ejercicio depende de la altura de las caderas.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'fondos', 'https://wger.de/media/exercise-images/1000/553266a8-a972-48c5-a014-b12afac66f65.png', 'https://wger.de/media/exercise-images/1000/553266a8-a972-48c5-a014-b12afac66f65.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Postura del Niño', 'Es una postura de descanso fundamental en yoga que estira la espalda, caderas y muslos. Desde una posición arrodillada, siéntate sobre tus talones e inclina el torso hacia adelante hasta que tu frente toque el suelo. Deja los brazos extendidos al frente o relájalos a los lados de tu cuerpo. Mantén la postura y respira profundamente.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats"]'::jsonb, 'lats', 'postura-del-nino', 'https://wger.de/media/exercise-images/1002/ddf91765-8045-4087-bece-de17f33332ce.png', 'https://wger.de/media/exercise-images/1002/ddf91765-8045-4087-bece-de17f33332ce.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Peso Muerto con Kettlebell', 'Coloca la pesa rusa entre tus pies. La clave es mantener la espalda completamente recta y empujar la cadera hacia atrás (es una bisagra de cadera, no una sentadilla) para tomar el agarre. Desde esa posición, contrae los glúteos y el abdomen para ponerte de pie con fuerza. Regresa al suelo de la misma manera controlada, iniciando de nuevo con la cadera hacia atrás.', 'accessory', 'intermediate', '["kettlebell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'peso-muerto-con-kettlebell', 'https://wger.de/media/exercise-images/1003/772d6e47-3865-4944-9255-7435d0b06782.png', 'https://wger.de/media/exercise-images/1003/a2b47fa8-79b4-4a21-920b-48765f562bc4.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Rotación de Cabeza', 'Este ejercicio mejora la movilidad y ayuda a aliviar la rigidez del cuello. Instrucciones: Sentado o de pie, con la espalda recta y los hombros relajados, gira lentamente tu cabeza hacia un lado como si intentaras mirar sobre tu hombro. Avanza solo hasta sentir un estiramiento suave, sin forzar el movimiento. Sostén esa posición por 5 segundos, regresa al centro con control y repite hacia el otro lado.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids"]'::jsonb, 'deltoids', 'rotacion-de-cabeza', 'https://wger.de/media/exercise-images/1007/757846d3-78e4-4068-bbca-62e567372c94.png', 'https://wger.de/media/exercise-images/1007/757846d3-78e4-4068-bbca-62e567372c94.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Curl de biceps alterno', 'Posición inicial: Comience de pie con pesas en cada mano, la espalda recta y los pies separados al ancho de las caderas. Tus brazos deben estar relajados, apuntando hacia abajo. Tus rodillas deben estar ligeramente flexionadas, tus abdominales contraídos y tus hombros hacia abajo. Pasos: Dobla un brazo por el codo, llevando la mancuerna hasta tu hombro. La parte superior del brazo debe permanecer inmóvil durante este movimiento. 2. Lleva la mancuerna hacia abajo hasta que tu brazo esté en su posición original relajada. Repita, cambiando de brazo.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-de-biceps-alterno', 'https://wger.de/media/exercise-images/1012/8270fdb8-28f1-4eff-b410-af8642085b3f.png', 'https://wger.de/media/exercise-images/1012/8270fdb8-28f1-4eff-b410-af8642085b3f.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Inclinaciones Laterales de Cabeza', 'Este es un estiramiento fundamental para aliviar la tensión en los músculos a los costados del cuello. Instrucciones: Sentado o de pie, con la espalda recta y los hombros relajados y abajo, inclina lentamente la cabeza hacia un lado, llevando la oreja en dirección al hombro hasta que sientas un estiramiento suave en el lado opuesto. Mantén el hombro del lado que se estira apuntando hacia abajo para maximizar la sensación. Sostén la posición por 15-30 segundos, regresa al centro con suavidad y repite hacia el otro lado.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats"]'::jsonb, 'lats', 'inclinaciones-laterales-de-cabeza', 'https://wger.de/media/exercise-images/1018/5bbd3879-b6fc-4aaa-9e8e-33ae9a688112.png', 'https://wger.de/media/exercise-images/1018/5f84cb9b-2d3a-48ff-87ec-b3d3950841f1.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Remo en Plancha con un Brazo', 'Comienza en una posición de plancha alta (como para hacer una flexión), pero con las manos agarrando unas mancuernas que están apoyadas en el suelo. Separa los pies un poco más que el ancho de tus caderas para tener una base más estable. Desde ahí, manteniendo el abdomen y los glúteos apretados para que tu cuerpo no se gire, jala una mancuerna hacia tu costado, llevando el codo hacia el techo. Haz una pausa arriba, baja la mancuerna de forma controlada y repite el movimiento. Completa todas las repeticiones de un lado antes de cambiar al otro.', 'accessory', 'intermediate', '["kettlebell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["biceps","hombros","espalda","core"]'::jsonb, 'biceps', 'remo-en-plancha-con-un-brazo', 'https://wger.de/media/exercise-images/1022/f74644fa-f43e-46bd-8603-6e3a2ee8ee2d.jpg', 'https://wger.de/media/exercise-images/1022/eef8fb9d-ae72-4e23-81da-4d62f2734332.jpg', 'wger.de', 'CC-BY-SA 4', ''),
  ('Hindu Pushups', 'Ejercicio para fortalecer los hombros y pectorales. Su nombre se debe a que se empieza en la postura de Yoga "Perro boca abajo", pasando a "Cobra" pero sin apoyar las piernas ni torso en el suelo para finalmente acabar con una flexión normal. El ejercicio también se puede realizar hacia atrás (de vuelta a la postura inicial). Como variación, tras hacer la flexión, se puede elevar la cadera para volver a la postura del perro boca abajo', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","hombros","pecho"]'::jsonb, 'pectorals', 'hindu-pushups', 'https://wger.de/media/exercise-images/1080/c4bf7ba1-6058-4d14-928f-7187885d5d57.webp', 'https://wger.de/media/exercise-images/1080/c4bf7ba1-6058-4d14-928f-7187885d5d57.webp', 'wger.de', 'CC-BY-SA 4', 'Imobard'),
  ('Press de suelo con mancuernas', 'Coge tus mancuernas y túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo (usa un banco si tienes uno). Empuja los pesos hacia arriba, extendiendo por completo los codos (A). Bájalos lentamente hasta que los brazos superiores descansen en el suelo (B) cerca del cuerpo. Haz una pausa aquí antes de empujar de forma explosiva hacia arriba. Aprieta el pecho con fuerza y repite.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'press-de-suelo-con-mancuernas', 'https://wger.de/media/exercise-images/1084/91dd5a95-1c45-46f2-a074-de41b6ad599b.jpg', 'https://wger.de/media/exercise-images/1084/91dd5a95-1c45-46f2-a074-de41b6ad599b.jpg', 'wger.de', 'CC-BY-SA 4', 'admin'),
  ('Flexiones con agarre estrecho', 'Colócate en una posición de plancha firme, llevando las manos cerca la una de la otra hasta que casi se toquen. (imagen 1) Flexiona los codos para bajar lentamente el pecho hacia el suelo (imagen 2). Mantén los codos cerca del cuerpo mientras te empujas de nuevo hacia arriba de forma explosiva. Repite. Asegúrate de tomarte tu tiempo al bajar en cada repetición, manteniendo una técnica precisa.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","espalda","pecho"]'::jsonb, 'pectorals', 'flexiones-con-agarre-estrecho', 'https://wger.de/media/exercise-images/1086/b2ee8d9b-0480-4992-8494-c223b37c2696.jpg', 'https://wger.de/media/exercise-images/1086/b2ee8d9b-0480-4992-8494-c223b37c2696.jpg', 'wger.de', 'CC-BY-SA 4', 'philip'),
  ('Cargada de potencia desde colgado con mancuernas', 'De pie, ponte erguido con tus mancuernas, sujetándolas a los costados. Flexiónate por las caderas para bajarlas hasta las rodillas (imagen 1). Vuelve a incorporarte con un ligero salto, usando el impulso para tirar de las mancuernas hasta los hombros (imagen 2). Ponte recto y luego bájalas de forma controlada hasta los costados y repite. Mantén esto rápido y explosivo; si tu ritmo cardíaco no se dispara, las estás haciendo mal.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'cargada-de-potencia-desde-colgado-con-mancuernas', 'https://wger.de/media/exercise-images/1087/d85f4e02-b20c-457c-bdfb-0b00e2d14150.jpg', 'https://wger.de/media/exercise-images/1087/d85f4e02-b20c-457c-bdfb-0b00e2d14150.jpg', 'wger.de', 'CC-BY-SA 4', 'philip'),
  ('Peso muerto sumo con mancuerna', 'Baja tu mancuerna al suelo entre las piernas. Adopta una postura amplia y, con la espalda recta, baja en sentadilla. Con la mancuerna en posición vertical, agárrala por la parte superior de la "cabeza" (imagen 1). Manteniendo el pecho arriba y el core activado, empuja el suelo, impulsándote de nuevo hacia arriba hasta quedar de pie (imagen 2). Repite. Si alcanzas fácilmente 20-30 repeticiones, usa dos mancuernas.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["knee_injury","back_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'peso-muerto-sumo-con-mancuerna', 'https://wger.de/media/exercise-images/1088/9f66b288-ce8f-4154-ba80-78fee267263c.jpg', 'https://wger.de/media/exercise-images/1088/9f66b288-ce8f-4154-ba80-78fee267263c.jpg', 'wger.de', 'CC-BY-SA 4', 'philip'),
  ('Abdominales rusas', 'sentado en el suelo agarramos la pesa rusa, flexionamos las piernas y las separamos del suelo. Ahora llevaremos a un lado y otro la pesa', 'core', 'intermediate', '["swiss_ball"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'abdominales-rusas', 'https://wger.de/media/exercise-images/1089/49f51716-535d-41dd-aeb5-cff5bb906bc1.jpeg', 'https://wger.de/media/exercise-images/1089/49f51716-535d-41dd-aeb5-cff5bb906bc1.jpeg', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Plancha a una mano alterna', 'En la posición de plancha correcta, coloque los pies a una distancia ligeramente superior a la anchura de los hombros. Levante y toque alternativamente el hombro opuesto con una mano.', 'core', 'intermediate', '["gym_mat"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["deltoids","hombros","gluteos","core"]'::jsonb, 'deltoids', 'plancha-a-una-mano-alterna', 'https://wger.de/media/exercise-images/1091/50c8912d-54ef-46c9-99d1-633b6196aa1e.jpg', 'https://wger.de/media/exercise-images/1091/50c8912d-54ef-46c9-99d1-633b6196aa1e.jpg', 'wger.de', 'CC-BY-SA 4', 'clafal'),
  ('Seated rear delt rise', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'seated-rear-delt-rise', 'https://wger.de/media/exercise-images/1098/fa5328a2-64cb-4afb-a283-b3d948ddaf3f.jpg', 'https://wger.de/media/exercise-images/1098/fa5328a2-64cb-4afb-a283-b3d948ddaf3f.jpg', 'wger.de', 'CC-BY-SA 4', 'philip'),
  ('Wall balls', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["swiss_ball"]'::jsonb, '["knee_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros","gluteos","piernas"]'::jsonb, 'deltoids', 'wall-balls', 'https://wger.de/media/exercise-images/1100/ab203e0c-8220-4537-987c-871eb259d687.jpg', 'https://wger.de/media/exercise-images/1100/ab203e0c-8220-4537-987c-871eb259d687.jpg', 'wger.de', 'CC-BY-SA 4', 'philip'),
  ('Seated Knee Tuck', 'Ejercicio de entrenamiento guiado.', 'core', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'seated-knee-tuck', 'https://wger.de/media/exercise-images/1105/36776818-799a-40bf-9eca-aebb3aa5008f.png', 'https://wger.de/media/exercise-images/1105/36776818-799a-40bf-9eca-aebb3aa5008f.png', 'wger.de', 'CC-BY-SA 4', 'utkb'),
  ('Biceps concentrado', 'El curl de concentración es un ejercicio clásico para desarrollar los bíceps un brazo a la vez. Se puede realizar inclinado o de rodillas, pero se realiza más a menudo sentado en un banco. Es excelente para enfatizar el pico del bíceps y, a menudo, se usa para terminar un entrenamiento de bíceps.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'biceps-concentrado', 'https://wger.de/media/exercise-images/1109/00b0a0bf-c14a-4f13-bb14-62c09030a1aa.png', 'https://wger.de/media/exercise-images/1109/00b0a0bf-c14a-4f13-bb14-62c09030a1aa.png', 'wger.de', 'CC-BY-SA 4', 'cshep442'),
  ('Flexiones | declinadas (decline)', 'Las flexiones declinadas son otra versión modificada de la flexión tradicional que trabaja los músculos del tren superior de una forma diferente. Para realizar una flexión declinada, eleva los pies sobre una superficie elevada, como un banco, una silla o un escalón, mientras colocas las manos en el suelo en posición de flexión. Baja el cuerpo hacia el suelo manteniendo una línea recta desde los hombros hasta los tobillos y luego empuja de nuevo hasta la posición inicial. A diferencia de la flexión inclinada, la flexión declinada pone más énfasis en los hombros y los tríceps, sin dejar de implicar los músculos del pecho en menor medida. Al elevar los pies aumentas la dificultad del ejercicio, ya que cargas más peso sobre el tren superior y obligas a los hombros y los tríceps a trabajar más ', 'accessory', 'intermediate', '["bench","incline_bench"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'flexiones-declinadas-decline', 'https://wger.de/media/exercise-images/1112/81f40bee-4adf-4317-8476-1a87706e3031.png', 'https://wger.de/media/exercise-images/1112/81f40bee-4adf-4317-8476-1a87706e3031.png', 'wger.de', 'CC-BY-SA 4', 'anon1337'),
  ('Remo gironda agarre cerrado', 'Siéntate en la máquina con los pies bien plantados, separados un poco más que la anchura de los hombros. Impulsa los talones y aprieta los glúteos. Sujétate al mango del cable. Siéntate erguido con las rodillas ligeramente flexionadas. Contrae los abdominales y la zona lumbar para mantener un ángulo perpendicular al suelo con el torso. Mueve los hombros hacia atrás y hacia abajo. Apriétalos mientras remas, pensando en sujetar un lápiz entre ellos. Al hacerlo, tira del mango hacia ti, aterrizando justo encima del ombligo. Haz una pausa antes de volver a colocar el mango, apretando los omóplatos. Una vez que hayas devuelto el peso a la pila, deja que los omóplatos se relajen, sin tirar del torso hacia adelante. Repite el movimiento.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lower_back","espalda"]'::jsonb, 'lower_back', 'remo-gironda-agarre-cerrado', 'https://wger.de/media/exercise-images/1117/2555c4c3-a84d-47db-b83b-cbf721f12e45.png', 'https://wger.de/media/exercise-images/1117/e74255c0-67a0-4309-b78d-2d79e6ff8c11.png', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Remo maquina agarre estrecho', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-maquina-agarre-estrecho', 'https://wger.de/media/exercise-images/1119/9b138ad2-5b80-42a8-bfff-93a960444ffe.png', 'https://wger.de/media/exercise-images/1119/9b138ad2-5b80-42a8-bfff-93a960444ffe.png', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Remo maquina agarre estrecho supino', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-maquina-agarre-estrecho-supino', 'https://wger.de/media/exercise-images/1120/df9a5256-e977-44d0-bc9c-b53253faeb22.png', 'https://wger.de/media/exercise-images/1120/df9a5256-e977-44d0-bc9c-b53253faeb22.png', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Jalón cerrado supino', 'Movimiento descendente • Tira de la barra hacia abajo para que pase cerca de tu barbilla y toque la parte superior de tu pecho. • Mantén el resto de tu cuerpo inmóvil.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'jalon-cerrado-supino', 'https://wger.de/media/exercise-images/1127/4942b7c0-6bda-4983-88e5-86547c3d445e.png', 'https://wger.de/media/exercise-images/1127/4942b7c0-6bda-4983-88e5-86547c3d445e.png', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Extensión de glúteos en polea', 'Esta actividad te permitirá ejercitar la zona del glúteo superior o mayor. Por ello, nunca puede faltar en tu rutina de ejercicios aislados para trabajar los glúteos. Colócate frente a una máquina de poleas y localiza el gancho inferior. Luego, sujétalo en las tobilleras para trabajar en polea baja. En relación con la postura, debes estar recto en todo momento. Presta especial atención a tu espalda para mantenerla recta y no lastimarte. Es recomendable que te sujetes a la máquina para tener más equilibrio. Con la pierna con la que estás sosteniendo el peso de la polea, realiza una extensión lenta hacia atrás sin flexionar la rodilla.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["glutes","gluteos"]'::jsonb, 'glutes', 'extension-de-gluteos-en-polea', 'https://wger.de/media/exercise-images/1131/3bcf3024-2dcc-4995-9694-55aa2c2e4a9a.png', 'https://wger.de/media/exercise-images/1131/3bcf3024-2dcc-4995-9694-55aa2c2e4a9a.png', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Jalón al pecho con agarre neutro', 'El jalón al pecho es un ejercicio importante para fortalecer la espalda y mejorar la postura, lo que puede contribuir a una vida más saludable. Para realizar este ejercicio correctamente y evitar lesiones, es importante seguir algunos pasos clave: Colócate frente a la máquina de poleas con las rodillas ligeramente dobladas y los pies en el suelo. Agarra el mango de la polea con las palmas enfrentadas y las manos separadas a la anchura de los hombros. Tira hacia abajo del mango hasta que toque o se acerque al pecho, manteniendo la posición durante uno o dos segundos. Vuelve a subir el mango lentamente a la posición inicial, asegurándote de mantener los brazos y las manos rectos y la espalda recta durante todo el movimiento.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["biceps","espalda"]'::jsonb, 'biceps', 'jalon-al-pecho-con-agarre-neutro', 'https://wger.de/media/exercise-images/1136/5778a8e9-c606-4843-89c8-9d9469eeb6e4.PNG', 'https://wger.de/media/exercise-images/1136/5778a8e9-c606-4843-89c8-9d9469eeb6e4.PNG', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Pull over en polea alta', 'De pie, de cara al aparato, con los pies ligeramente separados, la barra cogida en pronación, los brazos extendidos y las manos separadas a una distancia igual a la anchura de los hombros. Con la espalda fija y la banda abdominal contraída, inspira y lleva la barra hasta los muslos manteniendo los brazos extendidos (o los codos ligeramente flexionados). Espira al final del movimiento.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'pull-over-en-polea-alta', 'https://wger.de/media/exercise-images/1137/42f22229-c0a0-4bfc-aca6-66fe5e1ab10d.PNG', 'https://wger.de/media/exercise-images/1137/42f22229-c0a0-4bfc-aca6-66fe5e1ab10d.PNG', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Incline bench pulldown', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'incline-bench-pulldown', 'https://wger.de/media/exercise-images/1138/6c35fd79-ef35-4cf3-abf5-9c969457b8d4.PNG', 'https://wger.de/media/exercise-images/1138/6c35fd79-ef35-4cf3-abf5-9c969457b8d4.PNG', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Arabesco', 'Lleva todo tu peso sobre una pierna y mantén esa posición, conservando la cadera y la pelvis niveladas durante todo el ejercicio. Con la espalda en posición neutra, inclínate hacia delante mientras llevas la otra pierna hacia atrás y arriba. Después, con la fuerza de los glúteos, vuelve lentamente a la posición neutra.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'arabesco', 'https://wger.de/media/exercise-images/1141/c7be1cd1-46c5-4a86-a114-5f0fe861c3e0.jpg', 'https://wger.de/media/exercise-images/1141/c7be1cd1-46c5-4a86-a114-5f0fe861c3e0.jpg', 'wger.de', 'CC-BY-SA 4', 'cleen'),
  ('Back extensión', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '[]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'back-extension', 'https://wger.de/media/exercise-images/1143/6e21cb6c-da09-4bcd-b9d2-1ef75237b763.png', 'https://wger.de/media/exercise-images/1143/6e21cb6c-da09-4bcd-b9d2-1ef75237b763.png', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Extensión de tríceps en polea con cuerda', 'La extensión de tríceps en polea con cuerda es un ejercicio efectivo para trabajar los músculos del tríceps, específicamente el músculo braquial y el tríceps braquial. Este ejercicio se realiza utilizando una polea alta y una cuerda como accesorio. Beneficios del ejercicio Aislamiento del tríceps: Permite un enfoque específico en los músculos del tríceps, ayudando a desarrollar fuerza y masa muscular. Variedad de ángulos: La cuerda permite un rango de movimiento más natural, lo que puede ayudar a activar más fibras musculares. Control del peso: Puedes ajustar fácilmente la carga en la polea, lo que permite un entrenamiento progresivo. Cómo realizar la extensión de tríceps en polea con cuerda Posición inicial: Colócate de pie frente a la polea alta. Ajusta la polea a la altura adecuada y co', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'extension-de-triceps-en-polea-con-cuerda', 'https://wger.de/media/exercise-images/1185/c5ca283d-8958-4fd8-9d59-a3f52a3ac66b.jpg', 'https://wger.de/media/exercise-images/1185/c5ca283d-8958-4fd8-9d59-a3f52a3ac66b.jpg', 'wger.de', 'CC-BY-SA 4', 'anto.kreegyr'),
  ('One Arm Bent Row', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'one-arm-bent-row', 'https://wger.de/media/exercise-images/1186/1987a039-cf35-437e-bbdc-40c53dd7d053.jpg', 'https://wger.de/media/exercise-images/1186/1987a039-cf35-437e-bbdc-40c53dd7d053.jpg', 'wger.de', 'CC-BY-SA 4', 'anto.kreegyr'),
  ('Flexión lateral', 'Con una pesa en una mano, estiramos el brazo hacia abajo y flexionamos el otro brazo apoyando la mano en la cabeza. Ahora llevamos la mano con la pesa arriba y abajo girando el torso.', 'core', 'intermediate', '["dumbbell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'flexion-lateral', 'https://wger.de/media/exercise-images/1188/43e714e4-b736-4f3a-8ab4-97821fdff86a.jpg', 'https://wger.de/media/exercise-images/1188/43e714e4-b736-4f3a-8ab4-97821fdff86a.jpg', 'wger.de', 'CC-BY-SA 4', ''),
  ('Curls de bíceps alternos con mancuerna', 'Sujeta dos mancuernas, los brazos estirados, las manos a los costados y las palmas mirando hacia dentro. Flexiona un brazo cada vez y lleva el peso hacia arriba con un movimiento rápido. Al mismo tiempo, gira los brazos 90 grados justo al inicio del movimiento. En el punto más alto, gira las mancuernas un poco más hacia fuera. Sin pausa, baja el brazo de nuevo lentamente y haz lo mismo con el otro brazo. No dejes que tu cuerpo se balancee durante el ejercicio, todo el trabajo lo realiza el bíceps, que es el único músculo que debe moverse (presta atención a los codos).', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["back_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curls-de-biceps-alternos-con-mancuerna', 'https://wger.de/media/exercise-images/1192/651a4535-8210-4dbd-8f06-61d95fdd9963.png', 'https://wger.de/media/exercise-images/1192/651a4535-8210-4dbd-8f06-61d95fdd9963.png', 'wger.de', 'CC-BY-SA 4', 'Franpol'),
  ('Pallof Press', 'El Pallof press es un ejercicio antirrotación que entrena los músculos grandes y pequeños alrededor de la columna para resistir la rotación. Colócate en paralelo a la máquina de poleas o al punto de anclaje de la banda de resistencia y agarra el asa o la banda con ambas manos. Asegúrate de que tu torso quede de frente, lleva las manos al centro del pecho y empuja lentamente hacia fuera. Vuelve lentamente las manos al pecho y repite.', 'core', 'intermediate', '["cable_machine"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros","gluteos","core"]'::jsonb, 'deltoids', 'pallof-press', 'https://wger.de/media/exercise-images/1194/34c03421-0803-4859-a2b0-5710f2bd94cd.png', 'https://wger.de/media/exercise-images/1194/074e1766-4208-4a67-a211-9721772d99b0.png', 'wger.de', 'CC-BY-SA 4', 'prevail90'),
  ('Remo invertido', 'Mantén el cuerpo recto, retrae las escápulas y lleva el pecho hacia la barra para un entrenamiento eficaz de la espalda y el tren superior.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["biceps","espalda"]'::jsonb, 'biceps', 'remo-invertido', 'https://wger.de/media/exercise-images/1198/864906ac-4ac7-4e52-a886-c6bb97950a9f.jpg', 'https://wger.de/media/exercise-images/1198/864906ac-4ac7-4e52-a886-c6bb97950a9f.jpg', 'wger.de', 'CC-BY-SA 4', 'Gavru'),
  ('Flexión sobre los dedos', 'Posición de las manos: Comienza en posición de plancha con las manos directamente debajo de los hombros. Separa bien los dedos y apóyalos firmemente en el suelo. Colocación de los dedos: Levanta gradualmente las palmas del suelo, trasladando el peso a los dedos. Concéntrate en distribuir la carga de forma uniforme entre las yemas de los dedos y los pulgares. Alineación del cuerpo: Mantén una línea recta desde la cabeza hasta los talones para activar el core. Mantén el cuerpo en una posición controlada y estable durante todo el ejercicio. Fase de descenso: Flexiona lentamente los codos, bajando el pecho hacia el suelo. Asegura un movimiento controlado, manteniendo la estabilidad sobre las yemas de los dedos. Empuje hacia arriba: Empuja a través de las yemas de los dedos para estirar los bra', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'flexion-sobre-los-dedos', 'https://wger.de/media/exercise-images/1217/590e65db-de60-4727-b7eb-55f80af56043.png', 'https://wger.de/media/exercise-images/1217/590e65db-de60-4727-b7eb-55f80af56043.png', 'wger.de', 'CC-BY-SA 4', ''),
  ('Claps over the head', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'claps-over-the-head', 'https://wger.de/media/exercise-images/1223/bf20836a-23b0-4f50-8b98-cfdd97684527.webp', 'https://wger.de/media/exercise-images/1223/bf20836a-23b0-4f50-8b98-cfdd97684527.webp', 'wger.de', 'CC-BY-SA 4', 'Lynn_McIntyre'),
  ('Curls de bíceps abiertos con mancuernas', 'Sujeta una mancuerna en cada mano con las manos un poco más separadas que el ancho de los hombros y las palmas mirando hacia delante. Flexiona los codos y eleva las mancuernas hasta los hombros. Vuelve lentamente y repite.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curls-de-biceps-abiertos-con-mancuernas', 'https://wger.de/media/exercise-images/1225/39a0b7e7-9780-425d-84f5-56d10d1690ac.gif', 'https://wger.de/media/exercise-images/1225/39a0b7e7-9780-425d-84f5-56d10d1690ac.gif', 'wger.de', 'CC-BY-SA 4', 'Lynn_McIntyre'),
  ('Curl de bíceps con press de hombros con mancuernas', 'Flexiona los codos y eleva las mancuernas hasta los hombros. Empuja las mancuernas por encima de la cabeza mientras giras los brazos para que las palmas miren hacia delante. Invierte el movimiento para bajar. Repite el ejercicio.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury","elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-de-biceps-con-press-de-hombros-con-mancuernas', 'https://wger.de/media/exercise-images/1226/a6154dbd-67a0-4a36-8748-0f5af3865e83.jpg', 'https://wger.de/media/exercise-images/1226/a6154dbd-67a0-4a36-8748-0f5af3865e83.jpg', 'wger.de', 'CC-BY-SA 4', 'Lynn_McIntyre'),
  ('Remo para deltoides posterior con mancuernas', 'Sujeta una mancuerna en cada mano. Flexiónate por la cadera hasta que la espalda quede casi paralela al suelo. Deja que los brazos cuelguen hacia abajo. Mantén los brazos en línea con los hombros. Flexiona y eleva los codos hacia los lados hasta que los brazos queden paralelos al suelo. Vuelve lentamente y repite.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'remo-para-deltoides-posterior-con-mancuernas', 'https://wger.de/media/exercise-images/1227/57415c3c-2963-4130-9f6f-79f6a96113b6.gif', 'https://wger.de/media/exercise-images/1227/57415c3c-2963-4130-9f6f-79f6a96113b6.gif', 'wger.de', 'CC-BY-SA 4', 'Lynn_McIntyre'),
  ('Estiramiento de tríceps izquierdo', 'Coloca la mano izquierda en la espalda, agarra el codo izquierdo con la mano derecha y tira suavemente de él. Mantén esta posición durante unos segundos.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'estiramiento-de-triceps-izquierdo', 'https://wger.de/media/exercise-images/1230/9fd1e2fd-f2c4-432d-b3ae-5e5f24085777.webp', 'https://wger.de/media/exercise-images/1230/9fd1e2fd-f2c4-432d-b3ae-5e5f24085777.webp', 'wger.de', 'CC-BY-SA 4', 'Lynn_McIntyre'),
  ('Estiramiento de tríceps derecho', 'Coloca la mano derecha en la espalda, agarra el codo derecho con la mano izquierda y tira suavemente de él. Mantén esta posición durante unos segundos.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'estiramiento-de-triceps-derecho', 'https://wger.de/media/exercise-images/1231/b10457ce-5fa5-4d20-a32f-3c7100c6a9d9.webp', 'https://wger.de/media/exercise-images/1231/b10457ce-5fa5-4d20-a32f-3c7100c6a9d9.webp', 'wger.de', 'CC-BY-SA 4', 'Lynn_McIntyre'),
  ('Estiramiento de bíceps de pie izquierdo', 'Ponte de pie con el brazo izquierdo cerca de una pared. Extiende el brazo izquierdo y apoya la mano izquierda en la pared, luego gira suavemente el cuerpo hacia la derecha.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["biceps","hombros","pecho"]'::jsonb, 'biceps', 'estiramiento-de-biceps-de-pie-izquierdo', 'https://wger.de/media/exercise-images/1232/2b6de046-5806-49e3-bf36-b6fae16af021.png', 'https://wger.de/media/exercise-images/1232/2b6de046-5806-49e3-bf36-b6fae16af021.png', 'wger.de', 'CC-BY-SA 4', 'Lynn_McIntyre'),
  ('Estiramiento de bíceps de pie derecho', 'Ponte de pie con el brazo derecho cerca de una pared. Extiende el brazo derecho y apoya la mano derecha en la pared, luego gira suavemente el cuerpo hacia la izquierda.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["biceps","hombros","pecho"]'::jsonb, 'biceps', 'estiramiento-de-biceps-de-pie-derecho', 'https://wger.de/media/exercise-images/1233/d7d6f9e1-7834-4cca-bd3b-f9def33ff44d.png', 'https://wger.de/media/exercise-images/1233/d7d6f9e1-7834-4cca-bd3b-f9def33ff44d.png', 'wger.de', 'CC-BY-SA 4', 'Lynn_McIntyre'),
  ('Estiramiento de gemelos de pie', 'Este estiramiento trabaja el gastrocnemio (el músculo principal de la pantorrilla, que flexiona la rodilla y el pie). Es fácil de realizar en cualquier lugar. Todo lo que necesitas es una pared o una silla.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'estiramiento-de-gemelos-de-pie', 'https://wger.de/media/exercise-images/1239/5026373a-a7b4-4e26-a0aa-c46634205196.jpg', 'https://wger.de/media/exercise-images/1239/5026373a-a7b4-4e26-a0aa-c46634205196.jpg', 'wger.de', 'CC-BY-SA 4', 'erikocobra'),
  ('Elevación de talones a dos piernas', 'La elevación de talones a dos piernas es importante para fortalecer y crear control y estabilidad alrededor del tobillo y la rodilla, y para aportar equilibrio y control a la cadera y la pelvis.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'elevacion-de-talones-a-dos-piernas', 'https://wger.de/media/exercise-images/1243/53d4fabe-c994-4907-873f-8d82813a9832.png', 'https://wger.de/media/exercise-images/1243/53d4fabe-c994-4907-873f-8d82813a9832.png', 'wger.de', 'CC-BY-SA 4', 'erikocobra'),
  ('Sitting Calf Stretch (Dorsiflexion)', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'sitting-calf-stretch-dorsiflexion', 'https://wger.de/media/exercise-images/1274/bcffdf52-3c36-4b0c-b787-fb84f20bf82d.png', 'https://wger.de/media/exercise-images/1274/bcffdf52-3c36-4b0c-b787-fb84f20bf82d.png', 'wger.de', 'CC-BY-SA 4', 'erikocobra'),
  ('Plantarflexion Stretch with Band', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["resistance_band"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps"]'::jsonb, 'quadriceps', 'plantarflexion-stretch-with-band', 'https://wger.de/media/exercise-images/1275/0652d306-93eb-42f0-b564-7c3261ea809a.png', 'https://wger.de/media/exercise-images/1275/0652d306-93eb-42f0-b564-7c3261ea809a.png', 'wger.de', 'CC-BY-SA 4', 'erikocobra'),
  ('Remo con mancuernas en banco inclinado con apoyo en el pecho', 'Coloca un banco ajustable en un ángulo de 45 grados. Túmbate boca abajo con la cabeza colgando justo por encima del borde del banco. Agarra una mancuerna en cada mano y colócate con una buena postura: el core y los dorsales activados y los hombros neutros. Rema las mancuernas hacia la parte superior del abdomen y aprieta la espalda en la parte alta de la repetición. Por último, baja las mancuernas de nuevo a la posición inicial y repite hasta completar todas las repeticiones.', 'accessory', 'intermediate', '["bench","dumbbell"]'::jsonb, '["back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["biceps","espalda"]'::jsonb, 'biceps', 'remo-con-mancuernas-en-banco-inclinado-con-apoyo-en-el-pecho', 'https://wger.de/media/exercise-images/1283/e7262f70-7512-408a-8d00-4c499ef632fc.jpg', 'https://wger.de/media/exercise-images/1283/e7262f70-7512-408a-8d00-4c499ef632fc.jpg', 'wger.de', 'CC-BY-SA 4', 'carlos3c'),
  ('Talons fesses', 'Ejercicio de entrenamiento guiado.', 'cardio', 'beginner', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'talons-fesses', 'https://wger.de/media/exercise-images/1285/1ab8005d-41e4-4505-9a7d-5277d59bb3cd.jpg', 'https://wger.de/media/exercise-images/1285/1ab8005d-41e4-4505-9a7d-5277d59bb3cd.jpg', 'wger.de', 'CC-BY-SA 4', 'painDpice'),
  ('Curl de bíceps con barra en agarre invertido', 'Sujeta la barra con un agarre prono (palmas hacia abajo) aproximadamente al ancho de los hombros. Asegúrate de mantener la espalda recta, los hombros ligeramente hacia atrás y los brazos completamente extendidos. Flexiona la barra hacia arriba en dirección al pecho con un movimiento controlado, manteniendo los codos cerca del cuerpo. El movimiento debe ser fluido, sin balanceos ni uso de impulso. Una vez que la barra esté a la altura del pecho, haz una breve pausa para maximizar la contracción en los bíceps y los antebrazos. Baja lentamente la barra de nuevo a la posición inicial con un movimiento controlado, extendiendo por completo los brazos.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-de-biceps-con-barra-en-agarre-invertido', 'https://wger.de/media/exercise-images/1290/c05818bf-1c81-46df-9f24-42e354265388.png', 'https://wger.de/media/exercise-images/1290/c05818bf-1c81-46df-9f24-42e354265388.png', 'wger.de', 'CC-BY-SA 4', 'sTiKyt'),
  ('Cruce de poleas bajas', 'El cruce de poleas bajas es un movimiento de aislamiento que utiliza la polea para trabajar de forma específica la parte superior de los músculos pectorales. Es habitual en rutinas de tren superior y centradas en el pecho para ganar masa muscular, a menudo en combinación con presses o aperturas desde otros ángulos para trabajar todas las partes del pecho.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'cruce-de-poleas-bajas', 'https://wger.de/media/exercise-images/1296/c42782fe-337a-44f4-9079-7f6dedab4885.png', 'https://wger.de/media/exercise-images/1296/c42782fe-337a-44f4-9079-7f6dedab4885.png', 'wger.de', 'CC-BY-SA 4', 'JackSparrow'),
  ('Extensión de tríceps cruzada en polea alta', 'La extensión de tríceps cruzada en polea alta es un ejercicio de aislamiento para trabajar el tríceps, en particular la cabeza larga. Se utilizan cables y agarres sujetados con las manos contrarias, lo que permite un movimiento de empuje único que puede ser eficaz para desarrollar la fuerza del tríceps. A diferencia de los ejercicios que usan una barra recta o una cuerda, esta variante puede resultar más cómoda para tus muñecas y codos.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'extension-de-triceps-cruzada-en-polea-alta', 'https://wger.de/media/exercise-images/1298/ec4b83ec-5a8f-4303-9050-99ec4389bc2a.png', 'https://wger.de/media/exercise-images/1298/ec4b83ec-5a8f-4303-9050-99ec4389bc2a.png', 'wger.de', 'CC-BY-SA 4', 'JackSparrow'),
  ('Plancha frontal', 'La plancha es un ejercicio con el peso corporal. Como movimiento multifuncional, la plancha no solo trabaja tus abdominales, sino también la columna y la cadera. La plancha fortalece y tonifica todo tu cuerpo, mejora tu postura y tu equilibrio, reduce la grasa corporal y puede ayudar a acelerar tu metabolismo. Ejercicios como la «posición de plancha» ayudan a fortalecer la resistencia de los músculos abdominales estabilizadores. También puede ayudar a aliviar el dolor de espalda asociado a un debilitamiento de la función de los músculos estabilizadores del cuerpo. Las planchas son un ejercicio versátil que trabaja muchos de los grupos musculares más importantes del cuerpo, por lo que cualquier persona puede aplicarlas para mejorar la resistencia y la fuerza corporal general.', 'core', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'plancha-frontal', 'https://wger.de/media/exercise-images/1307/321d796a-f394-40b8-a1ea-874bbed6ecee.png', 'https://wger.de/media/exercise-images/1307/321d796a-f394-40b8-a1ea-874bbed6ecee.png', 'wger.de', 'CC-BY-SA 4', 'hektkaso'),
  ('Lateral Push Off', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'lateral-push-off', 'https://wger.de/media/exercise-images/1325/d8372291-6725-452a-9711-6321c061e354.jpg', 'https://wger.de/media/exercise-images/1325/d8372291-6725-452a-9711-6321c061e354.jpg', 'wger.de', 'CC-BY-SA 4', 'cleen'),
  ('Forearm Curls (underhand grip)', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'forearm-curls-underhand-grip', 'https://wger.de/media/exercise-images/1333/89f43354-32e3-473a-9bcf-caca51f1a8e3.webp', 'https://wger.de/media/exercise-images/1333/89f43354-32e3-473a-9bcf-caca51f1a8e3.webp', 'wger.de', 'CC-BY-SA 4', 'Anastasious'),
  ('Extensión de tríceps sobre la cabeza (mancuerna)', 'Fija los codos Activa la musculatura No uses impulso Movimiento controlado Movimiento lento No sobreextiendas', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["triceps"]'::jsonb, 'triceps', 'extension-de-triceps-sobre-la-cabeza-mancuerna', 'https://wger.de/media/exercise-images/1336/ebf88217-df26-4ef7-94cb-f0c2220c6abe.webp', 'https://wger.de/media/exercise-images/1336/ebf88217-df26-4ef7-94cb-f0c2220c6abe.webp', 'wger.de', 'CC-BY-SA 4', 'Anastasious'),
  ('Elevación de hombros (mancuerna)', 'Activa la musculatura No uses impulso Movimiento controlado Movimiento lento Mantén siempre el brazo flexionado No sobreextiendas', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'elevacion-de-hombros-mancuerna', 'https://wger.de/media/exercise-images/1338/9d157b4d-5af0-43c1-bd34-f52144ba1b54.webp', 'https://wger.de/media/exercise-images/1338/9d157b4d-5af0-43c1-bd34-f52144ba1b54.webp', 'wger.de', 'CC-BY-SA 4', 'Anastasious'),
  ('Extensiones de espalda baja', 'Activa la musculatura Levanta un poco los glúteos Movimiento controlado Movimiento lento No uses impulso Mantén el torso recto', 'accessory', 'intermediate', '[]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["lower_back"]'::jsonb, 'lower_back', 'extensiones-de-espalda-baja', 'https://wger.de/media/exercise-images/1348/a3769120-2445-49f2-97d3-afc1238bfc2a.webp', 'https://wger.de/media/exercise-images/1348/a3769120-2445-49f2-97d3-afc1238bfc2a.webp', 'wger.de', 'CC-BY-SA 4', 'Anastasious'),
  ('Press hex con mancuernas', 'Activa la musculatura Coloca los pies en posición amplia Movimiento controlado Movimiento lento Lleva los pesos hacia la parte baja del pecho/el abdomen', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["triceps","pecho"]'::jsonb, 'triceps', 'press-hex-con-mancuernas', 'https://wger.de/media/exercise-images/1353/138cb483-7d4d-4519-b029-63e4269810a6.webp', 'https://wger.de/media/exercise-images/1353/138cb483-7d4d-4519-b029-63e4269810a6.webp', 'wger.de', 'CC-BY-SA 4', 'Anastasious'),
  ('Blackroll', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats"]'::jsonb, 'lats', 'blackroll', 'https://wger.de/media/exercise-images/1363/1dba566b-e799-4bde-abb0-c011a3c75e52.webp', 'https://wger.de/media/exercise-images/1363/1dba566b-e799-4bde-abb0-c011a3c75e52.webp', 'wger.de', 'CC-BY-SA 4', 'Anastasious'),
  ('Giro de torso', 'Giro de torso de pie: ¡Trabaja tu core y mejora tu flexibilidad con este ejercicio dinámico de pie! El giro de torso de pie consiste en girar el torso mientras mantienes los pies y las caderas estables, activando los oblicuos y estirando toda la parte superior del cuerpo. Este movimiento ayuda a: fortalecer los músculos del core, aumentar la flexibilidad de la columna y el torso, mejorar la postura y el equilibrio, y potenciar el rendimiento atlético general. ¡Realiza 3 series de 10-15 repeticiones, girando hacia cada lado, para sentir los beneficios de este ejercicio eficaz y eficiente!', 'core', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'giro-de-torso', 'https://wger.de/media/exercise-images/1377/12e7a231-d36a-4992-bf57-ff7bfe0f3ae4.jpg', 'https://wger.de/media/exercise-images/1377/12e7a231-d36a-4992-bf57-ff7bfe0f3ae4.jpg', 'wger.de', 'CC-BY-SA 4', 'brucem'),
  ('Elevaciones laterales en polea (a un brazo)', 'La elevación lateral en polea a un brazo es una variante de la elevación lateral y un ejercicio que se utiliza para desarrollar los músculos de los hombros. Coloca una polea en la posición más baja posible y engancha un agarre individual. Cruza el brazo por delante del cuerpo y sujeta el agarre con un agarre neutro. Mantén el codo ligeramente flexionado y tira del agarre cruzando el cuerpo mientras elevas lateralmente. Baja el agarre lentamente y de forma controlada hasta la posición inicial.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'elevaciones-laterales-en-polea-a-un-brazo', 'https://wger.de/media/exercise-images/1378/7c1fcf34-fb7e-45e7-a0c1-51f296235315.jpg', 'https://wger.de/media/exercise-images/1378/7c1fcf34-fb7e-45e7-a0c1-51f296235315.jpg', 'wger.de', 'CC-BY-SA 4', 'carlos3c'),
  ('Patadas de isquiotibiales', 'Ponte de pie con los pies separados al ancho de las caderas y extiende un brazo frente a ti. Eleva esa pierna hacia adelante y bájala de nuevo manteniéndola lo más recta posible y con los dedos del pie apuntando hacia arriba. Repite con la otra pierna.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios"]'::jsonb, 'hamstrings', 'patadas-de-isquiotibiales', 'https://wger.de/media/exercise-images/1387/a2cf7eda-5540-4105-b30e-1c2f2679a6c7.png', 'https://wger.de/media/exercise-images/1387/a2cf7eda-5540-4105-b30e-1c2f2679a6c7.png', 'wger.de', 'CC-BY-SA 4', 'captive0592'),
  ('Good Morning', 'Ponte de pie con los pies separados más que el ancho de los hombros (postura ancha) y coloca las manos en las caderas. Flexiona desde las caderas y baja el torso hacia el suelo manteniendo la espalda recta, luego vuelve a subir.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios"]'::jsonb, 'hamstrings', 'good-morning', 'https://wger.de/media/exercise-images/1392/a02c9c7d-f42d-43e0-9946-1b99b014daee.png', 'https://wger.de/media/exercise-images/1392/af848376-3db3-4b16-a056-4aa936d49da4.png', 'wger.de', 'CC-BY-SA 4', 'captive0592'),
  ('Curl inclinado con mancuernas', 'Sentado en un banco con el respaldo inclinado en un ángulo de 40 a 60 grados. Deja que tus brazos cuelguen hacia el suelo. Sujeta una mancuerna en cada mano en supinación.', 'accessory', 'intermediate', '["bench","dumbbell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-inclinado-con-mancuernas', 'https://wger.de/media/exercise-images/1448/2184e68c-32b5-413f-a7c1-4a2d1bb98c35.png', 'https://wger.de/media/exercise-images/1448/2184e68c-32b5-413f-a7c1-4a2d1bb98c35.png', 'wger.de', 'CC-BY-SA 4', 'M9'),
  ('Estiramiento de rodilla al pecho', 'El estiramiento de rodilla al pecho es un ejercicio simple pero efectivo para aliviar la tensión en la zona lumbar y mejorar la movilidad de la cadera. Para realizarlo, acuéstate de espaldas con las piernas extendidas. Lleva una rodilla hacia el pecho y abraza la pierna con ambas manos, sujetando la espinilla o la parte posterior del muslo. Tira suavemente de la rodilla hacia el pecho mientras mantienes la otra pierna estirada en el suelo. Mantén el estiramiento durante 15–30 segundos y luego cambia de lado. Para un estiramiento más profundo, puedes llevar ambas rodillas al pecho al mismo tiempo.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lower_back","gluteos"]'::jsonb, 'lower_back', 'estiramiento-de-rodilla-al-pecho', 'https://wger.de/media/exercise-images/1452/85a6b9de-4eec-445b-8ebb-f1950b076aba.png', 'https://wger.de/media/exercise-images/1452/85a6b9de-4eec-445b-8ebb-f1950b076aba.png', 'wger.de', 'CC-BY-SA 4', 'hpmbala@gmail.com'),
  ('Abdominal con golpe de codo', 'Este es un movimiento de rotación de arriba hacia abajo, y es un poco más explosivo también. Tumbado con las rodillas flexionadas y los pies en el suelo, incorpórate y luego lleva el codo izquierdo cruzando todo el cuerpo hacia la derecha, después vuelve al centro y finalmente baja. Luego haz el otro lado.', 'core', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'abdominal-con-golpe-de-codo', 'https://wger.de/media/exercise-images/1479/0305d98e-0887-4c0c-8992-7c220814efc2.webp', 'https://wger.de/media/exercise-images/1479/0305d98e-0887-4c0c-8992-7c220814efc2.webp', 'wger.de', 'CC-BY-SA 4', 'Moffi'),
  ('Extensión de tríceps por encima de la cabeza', 'Extensión de tríceps por encima de la cabeza con barra Z – Guía rápida La posición por encima de la cabeza enfatiza la cabeza larga del tríceps (porque se estira bajo carga), aunque el ejercicio sí involucra las tres cabezas del tríceps (larga, lateral y medial) en cierta medida durante la extensión. Preparación : Siéntate en un banco (o de pie) y sujeta una barra Z con un agarre estrecho por encima. Levanta la barra por encima de la cabeza, con los brazos completamente extendidos. Mantén el core firme y los codos cerca de la cabeza. Ejecución : Baja lentamente la barra por detrás de la cabeza flexionando los codos hasta que alcancen unos 90°. Mantén los codos apuntando hacia delante (sin abrirlos hacia fuera). Final : Extiende los brazos de nuevo hacia arriba hasta la posición inicial, co', 'accessory', 'intermediate', '["sz-bar"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'extension-de-triceps-por-encima-de-la-cabeza', 'https://wger.de/media/exercise-images/1519/fab7f641-27d4-40b5-8edd-1a0a137bfd94.gif', 'https://wger.de/media/exercise-images/1519/fab7f641-27d4-40b5-8edd-1a0a137bfd94.gif', 'wger.de', 'CC-BY-SA 4', 'benjamin.yildiz@proton.me'),
  ('Pendular hack', 'Pendular hack, realizado en máquina pendular', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps"]'::jsonb, 'quadriceps', 'pendular-hack', 'https://wger.de/media/exercise-images/1521/e4e4aa78-3c96-4b1d-95c0-f9f73a0779d0.webp', 'https://wger.de/media/exercise-images/1521/e4e4aa78-3c96-4b1d-95c0-f9f73a0779d0.webp', 'wger.de', 'CC-BY-SA 4', 'polloperro'),
  ('Push-Up', 'La flexión es un ejercicio fundamental con peso corporal que trabaja el pecho, los brazos y los hombros, a la vez que trabaja el core para lograr estabilidad. No requiere equipo y es excelente para fortalecer la parte superior del cuerpo. Instrucciones: Comience en posición de plancha con las manos colocadas ligeramente más anchas que el ancho de los hombros, los pies juntos y el cuerpo en línea recta desde la cabeza hasta los talones. Contraiga el torso y baje el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo o ligeramente separados. Baje hasta que el pecho casi toque el suelo, manteniendo la columna neutra. Empuje con las palmas de las manos para volver a la posición inicial, extendiendo completamente los brazos.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'push-up', 'https://wger.de/media/exercise-images/1551/a6a9e561-3965-45c6-9f2b-ee671e1a3a45.png', 'https://wger.de/media/exercise-images/1551/a6a9e561-3965-45c6-9f2b-ee671e1a3a45.png', 'wger.de', 'CC-BY-SA 4', 'Settebello'),
  ('Flexión con palmada', 'La flexión con palmada es un movimiento explosivo del tren superior que desarrolla potencia y la fuerza de las fibras musculares de contracción rápida. Añade un desafío pliométrico a la flexión tradicional, ya que exige que las manos se separen del suelo en mitad de la repetición. Empieza en una posición sólida de flexión, con las manos algo más anchas que el ancho de los hombros y el core activado Baja el cuerpo de forma explosiva y empújate del suelo con suficiente fuerza para levantar las manos. Da una palmada rápida a la altura del pecho antes de devolver las manos al suelo. Aterriza con los codos ligeramente flexionados para absorber el impacto y pasa de inmediato a la siguiente repetición', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'flexion-con-palmada', 'https://wger.de/media/exercise-images/1554/49207a62-8799-4b47-8c0b-7bde02926f3d.png', 'https://wger.de/media/exercise-images/1554/49207a62-8799-4b47-8c0b-7bde02926f3d.png', 'wger.de', 'CC-BY-SA 4', 'Settebello'),
  ('Devil''s Press', 'El Devil''s Press es un movimiento híbrido que combina un burpee con mancuernas y un arrancada (snatch) con dos mancuernas. Es un ejercicio de cuerpo completo y alta intensidad que desarrolla fuerza, potencia y acondicionamiento metabólico. Empieza con una mancuerna en cada mano y realiza un burpee, dejando que el pecho toque el suelo mientras sujetas las mancuernas. Salta de forma explosiva llevando los pies hacia delante y balancea las mancuernas entre las piernas. Impulsa las mancuernas por encima de la cabeza en un solo movimiento continuo, bloqueando los brazos. Baja las mancuernas con control para volver a la posición inicial y repite', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","hombros","gluteos","pecho"]'::jsonb, 'pectorals', 'devil-s-press', 'https://wger.de/media/exercise-images/1556/a23c820b-e08b-4911-a6a4-80f16c15d2e0.png', 'https://wger.de/media/exercise-images/1556/a23c820b-e08b-4911-a6a4-80f16c15d2e0.png', 'wger.de', 'CC-BY-SA 4', 'Settebello'),
  ('Curl alterno de martillo con mancuernas', 'De pie, con las rodillas ligeramente dobladas y la espalda recta. Sujeta una mancuerna en cada mano, en un agarre neutral a lo largo del cuerpo.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["biceps"]'::jsonb, 'biceps', 'curl-alterno-de-martillo-con-mancuernas', 'https://wger.de/media/exercise-images/1567/0a8c155c-a48e-47e8-9df3-e39f025c6cad.png', 'https://wger.de/media/exercise-images/1567/0a8c155c-a48e-47e8-9df3-e39f025c6cad.png', 'wger.de', 'CC-BY-SA 4', 'Mariano_O'),
  ('Bird Dog', 'El Bird Dog es un ejercicio de estabilidad del core que mejora el equilibrio, la coordinación y la alineación de la columna. Es un movimiento de bajo impacto, ideal para fortalecer la cadena posterior y mejorar el control funcional general. Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas, manteniendo la columna neutra. Extiende el brazo derecho hacia delante y la pierna izquierda hacia atrás a la vez, manteniendo las caderas niveladas. Haz una breve pausa en la extensión completa mientras activas el core y los glúteos. Vuelve a la posición inicial y repite por el lado contrario', 'core', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["elbow_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'bird-dog', 'https://wger.de/media/exercise-images/1572/3d14e761-a73d-49da-8804-f3016a7573ff.png', 'https://wger.de/media/exercise-images/1572/3d14e761-a73d-49da-8804-f3016a7573ff.png', 'wger.de', 'CC-BY-SA 4', 'Settebello'),
  ('Rueda abdominal', 'Posición inicial : Arrodíllate en el suelo con la rueda abdominal frente a ti. Agarra la rueda : Sujeta los mangos con firmeza. Despliega : Rueda lentamente hacia delante, extendiendo el cuerpo mientras mantienes el core apretado. Regresa : Tira de la rueda de vuelta hacia las rodillas, manteniendo la tensión en el core.', 'core', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'rueda-abdominal', 'https://wger.de/media/exercise-images/1573/a9ab402b-61ef-4d60-b91a-df52bf7f41a9.jpg', 'https://wger.de/media/exercise-images/1573/662db55d-68d0-4297-8215-3dcf6c21c778.jpg', 'wger.de', 'CC-BY-SA 4', 'lhegedus'),
  ('Press de trapecio', 'Tumbado boca arriba con el brazo apuntando recto hacia arriba y el codo completamente extendido, usa únicamente el hombro para levantar el peso tan alto como te resulte cómodo y bájalo de nuevo hasta la posición de reposo.', 'accessory', 'intermediate', '["barbell","bench","dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids"]'::jsonb, 'deltoids', 'press-de-trapecio', 'https://wger.de/media/exercise-images/1581/b71a6710-5798-4639-ac5a-22a2cdae2036.jpg', 'https://wger.de/media/exercise-images/1581/b71a6710-5798-4639-ac5a-22a2cdae2036.jpg', 'wger.de', 'CC-BY-SA 4', 'CptnFatbeard'),
  ('Rotación interna tumbado de lado', 'Tumbado de lado y usando el brazo más cercano al banco, mantén una flexión de 90 grados en el codo y deja que el peso caiga hacia el suelo por delante del banco, tan bajo como te resulte cómodo. Sube el peso usando únicamente la rotación del hombro hacia el hombro contrario.', 'accessory', 'intermediate', '["barbell","bench","dumbbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["deltoids"]'::jsonb, 'deltoids', 'rotacion-interna-tumbado-de-lado', 'https://wger.de/media/exercise-images/1582/5094fe30-eea2-4269-b0de-4b8a20558fd7.png', 'https://wger.de/media/exercise-images/1582/5094fe30-eea2-4269-b0de-4b8a20558fd7.png', 'wger.de', 'CC-BY-SA 4', 'CptnFatbeard'),
  ('Sentadilla split en máquina Smith', 'La "Sentadilla split en máquina Smith" es un ejercicio de fuerza realizado en la máquina Smith, ideal para trabajar las piernas y los glúteos. Consiste en colocar un pie adelante y el otro atrás, bajando el cuerpo hasta que el muslo delantero quede paralelo al suelo mientras la barra se desliza verticalmente a lo largo de la máquina. Este ejercicio ayuda a mejorar la estabilidad, corregir desequilibrios musculares y reduce la tensión en la espalda, proporcionando un entorno seguro para el entrenamiento de fuerza.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","piernas"]'::jsonb, 'hamstrings', 'sentadilla-split-en-maquina-smith', 'https://wger.de/media/exercise-images/1593/9815fcd6-cf40-4ddd-9b38-2eac25973de1.gif', 'https://wger.de/media/exercise-images/1593/9815fcd6-cf40-4ddd-9b38-2eac25973de1.gif', 'wger.de', 'CC-BY-SA 4', 'workout@rooven.anonaddy.me'),
  ('Zancada lateral deslizante', 'Ponte de pie erguido con los pies separados al ancho de las caderas, sujetando una pesa rusa cerca del pecho en posición goblet. Coloca un pie sobre un slider, un disco deslizante o una toalla. Mantén el pecho erguido y el core activado. Desliza lentamente el pie hacia el lado mientras flexionas la rodilla contraria, bajando las caderas hacia una zancada lateral. Mantén la rodilla de la pierna que trabaja alineada con los dedos del pie y evita que se hunda hacia dentro. La pierna que no trabaja permanece estirada y se desliza suavemente por el suelo. Empuja con el talón de la pierna flexionada para volver a la posición inicial mientras mantienes el control de la pesa rusa.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos","piernas"]'::jsonb, 'hamstrings', 'zancada-lateral-deslizante', 'https://wger.de/media/exercise-images/1604/7695428e-bfed-4021-b987-498d93153995.png', 'https://wger.de/media/exercise-images/1604/7695428e-bfed-4021-b987-498d93153995.png', 'wger.de', 'CC-BY-SA 4', 'RiccaBaro'),
  ('Sentadilla con pesa rusa', 'Separar los pies a una distancia mayor que la anchura de los hombros, con los dedos de los pies apuntando hacia afuera.Manténer la espalda recta, los hombros hacia atrás y el pecho erguido. Las rodillas deben seguir la misma dirección que los dedos de los pies y no moverse hacia adelante. Al subir, es recomendable contraer los glúteos para maximizar la efectividad del ejercicio.', 'accessory', 'intermediate', '["kettlebell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos","piernas"]'::jsonb, 'hamstrings', 'sentadilla-con-pesa-rusa', 'https://wger.de/media/exercise-images/1612/3dc33f57-2786-4305-8b91-e011d7055923.jpg', 'https://wger.de/media/exercise-images/1612/e719b872-d122-4e2d-be17-bd2babfe457a.jpg', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Patada de glúteo con banda elástica', 'Una patada de glúteos con banda elástica es un ejercicio que se realiza a gatas. Se ancla una banda de resistencia a la parte posterior de la rodilla y se patea el talón hacia atrás y arriba, apretando el glúteo en la parte superior del movimiento, manteniendo el torso estable y la espalda recta para trabajar y fortalecer los músculos de los glúteos.', 'accessory', 'intermediate', '["resistance_band"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["glutes","gluteos"]'::jsonb, 'glutes', 'patada-de-gluteo-con-banda-elastica', 'https://wger.de/media/exercise-images/1613/a851fe9d-771f-44da-82f0-799e02ae3fd1.jpg', 'https://wger.de/media/exercise-images/1613/a851fe9d-771f-44da-82f0-799e02ae3fd1.jpg', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Cinta de correr', 'Es un entrenamiento cardiovascular que se realiza en una cinta de correr para mejorar la resistencia, quemar calorías y promover la salud del corazón. Ofrece múltiples beneficios, como la capacidad de ajustar fácilmente la velocidad e inclinación, lo que permite realizar diversos entrenamientos, desde caminatas en pendiente hasta carreras a intervalos de alta intensidad (HIIT) y carreras de tempo. Para optimizar los resultados, es importante variar los entrenamientos. Beneficios del cardio en cinta: Mejora de la salud cardiovascular: El ejercicio aeróbico regular en la cinta fortalece el corazón y los pulmones, lo que puede ayudar a prevenir enfermedades cardíacas. Pérdida de peso: Al quemar calorías, el entrenamiento en cinta puede ser una herramienta eficaz para la pérdida de peso y el m', 'cardio', 'beginner', '["none_(bodyweight_exercise)"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'cinta-de-correr', 'https://wger.de/media/exercise-images/1615/7792295c-83b6-4ea8-9353-ce02f0ad2559.jpg', 'https://wger.de/media/exercise-images/1615/7792295c-83b6-4ea8-9353-ce02f0ad2559.jpg', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Patada de burro con mancuerna', 'La patada de burro con mancuerna es un ejercicio efectivo para trabajar los músculos de los glúteos y los isquiotibiales. Este ejercicio se realiza generalmente en una posición de cuatro patas, utilizando una mancuerna para aumentar la resistencia. A continuación, se describen los pasos para realizarlo correctamente. Posición Inicial: Colócate en una posición de cuatro patas sobre una colchoneta, con las manos alineadas con los hombros y las rodillas alineadas con las caderas. Colocación de la Mancuerna: Toma una mancuerna y colócala detrás de la rodilla de la pierna que vas a levantar. Asegúrate de que esté bien sujeta para evitar que se caiga durante el ejercicio. Ejercicio: Inhala y, al exhalar, levanta la pierna con la mancuerna hacia arriba, manteniendo la rodilla flexionada en un áng', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'patada-de-burro-con-mancuerna', 'https://wger.de/media/exercise-images/1616/97e6fd98-2ca6-486f-b9b2-f0499fe38044.jpg', 'https://wger.de/media/exercise-images/1616/97e6fd98-2ca6-486f-b9b2-f0499fe38044.jpg', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Cardio en bicicleta estática', 'Beneficios del Cardio en Bicicleta Estática El cardio en bicicleta estática es una excelente forma de ejercicio que ofrece múltiples beneficios para la salud y el bienestar. Aquí te detallo algunos de los más destacados: Mejora de la Salud Cardiovascular Fortalece el corazón: El ejercicio regular ayuda a mejorar la eficiencia del corazón y a reducir el riesgo de enfermedades cardiovasculares. Aumenta la circulación: Mejora el flujo sanguíneo, lo que puede ayudar a reducir la presión arterial. Quema de Calorías y Pérdida de Peso Eficiente para quemar calorías: Dependiendo de la intensidad, puedes quemar entre 400 y 600 calorías por hora. Ayuda en la pérdida de peso: Combinado con una dieta equilibrada, el cardio en bicicleta estática puede ser efectivo para perder peso. Fortalecimiento Musc', 'cardio', 'beginner', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'cardio-en-bicicleta-estatica', 'https://wger.de/media/exercise-images/1618/c18baedc-ff98-4fb2-b4f5-38a05c12f637.png', 'https://wger.de/media/exercise-images/1618/c18baedc-ff98-4fb2-b4f5-38a05c12f637.png', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Elevación de gemelos sentado con mancuerna', 'La elevación de gemelos sentado con mancuerna es un ejercicio específico para fortalecer los músculos de la parte inferior de la pierna. Sigue el mismo patrón de movimiento que la versión en máquina: colocas el peso sobre las rodillas y, al extender y flexionar los tobillos, mueves el peso.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'elevacion-de-gemelos-sentado-con-mancuerna', 'https://wger.de/media/exercise-images/1620/edd40e39-e337-4460-a8dd-6127d40ddd16.jpeg', 'https://wger.de/media/exercise-images/1620/edd40e39-e337-4460-a8dd-6127d40ddd16.jpeg', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Remo unilateral en polea', 'Coloca un banco vertical frente a la máquina de remo en polea. Posiciónalo de manera que puedas concentrarte en un solo lado y luego realiza tracciones lentas, enfocándote en los músculos laterales y asegurando la tensión en esos músculos cuando estés en posición estirada.', 'accessory', 'intermediate', '["bench","cable_machine"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-unilateral-en-polea', 'https://wger.de/media/exercise-images/1621/ca1bc68d-9c36-4dd3-8ec4-496c57b5c564.jpg', 'https://wger.de/media/exercise-images/1621/1bf3ee54-207c-4b53-b057-15adc1dd6128.png', 'wger.de', 'CC-BY-SA 4', 'Rottekongen'),
  ('Pullover/remo con cuerda', 'Coloca un banco delante de la máquina de remo con polea. Inclínate sobre el banco para hacer un remo/pullover con la cuerda que trabaja los dorsales. Mira la imagen.', 'accessory', 'intermediate', '["cable_machine","incline_bench"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'pullover-remo-con-cuerda', 'https://wger.de/media/exercise-images/1634/9a4704d3-1b25-43e3-b244-3885f4d3db87.png', 'https://wger.de/media/exercise-images/1634/9a4704d3-1b25-43e3-b244-3885f4d3db87.png', 'wger.de', 'CC-BY-SA 4', 'Rottekongen'),
  ('Modified pulldown', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["cable_machine","incline_bench"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'modified-pulldown', 'https://wger.de/media/exercise-images/1635/b8c34e3a-7474-41ea-99e3-8d7fdb1e12d6.png', 'https://wger.de/media/exercise-images/1635/b8c34e3a-7474-41ea-99e3-8d7fdb1e12d6.png', 'wger.de', 'CC-BY-SA 4', 'Rottekongen'),
  ('Remo a un brazo', 'Sentado en el suelo, usa una polea alta con un agarre individual para hacer jalones al pecho, centrándote en un estiramiento largo de los dorsales.', 'accessory', 'intermediate', '["cable_machine","incline_bench"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-a-un-brazo', 'https://wger.de/media/exercise-images/1637/a1fbe83a-a3e5-49f6-a2c2-5d5b533c2be8.png', 'https://wger.de/media/exercise-images/1637/a1fbe83a-a3e5-49f6-a2c2-5d5b533c2be8.png', 'wger.de', 'CC-BY-SA 4', 'Rottekongen'),
  ('Cargada y press con barra', 'Este ejercicio consiste en levantar una barra desde el suelo hasta los hombros y luego empujarla por encima de la cabeza. Es un movimiento compuesto que trabaja varios grupos musculares, incluidas las piernas, la espalda, los hombros y los brazos. Se utiliza a menudo en programas de fuerza y acondicionamiento para mejorar la potencia y el rendimiento atlético en general.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","hombros","pecho"]'::jsonb, 'pectorals', 'cargada-y-press-con-barra', 'https://wger.de/media/exercise-images/1638/046c09b0-c35d-48d0-a552-39dd49f956d2.webp', 'https://wger.de/media/exercise-images/1638/046c09b0-c35d-48d0-a552-39dd49f956d2.webp', 'wger.de', 'CC-BY-SA 4', 'Rottekongen'),
  ('Face pull inclinado con mancuernas', 'Este ejercicio consiste en usar mancuernas para realizar un face pull inclinado, que trabaja la parte alta de la espalda y los hombros. El movimiento consiste en tirar de los pesos hacia la cara manteniendo los codos altos y juntando las escápulas.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["lats","hombros","espalda"]'::jsonb, 'lats', 'face-pull-inclinado-con-mancuernas', 'https://wger.de/media/exercise-images/1639/8927346e-f5ca-4795-bdf1-5ac9309401e7.webp', 'https://wger.de/media/exercise-images/1639/8927346e-f5ca-4795-bdf1-5ac9309401e7.webp', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Sentadilla frontal con mancuernas', 'En este ejercicio sostienes una mancuerna en cada mano a la altura de los hombros y realizas una sentadilla. Trabaja la musculatura del tren inferior, incluidos los cuádriceps, los isquiotibiales y los glúteos, al tiempo que activa el core y el tren superior.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["knee_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'sentadilla-frontal-con-mancuernas', 'https://wger.de/media/exercise-images/1640/bdea82f1-15ef-4649-8b5a-1303cfc178e7.webp', 'https://wger.de/media/exercise-images/1640/bdea82f1-15ef-4649-8b5a-1303cfc178e7.webp', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Peso muerto a una pierna con pesa rusa', 'En este ejercicio sostienes una pesa rusa en una mano y te mantienes de pie sobre una pierna mientras te inclinas hacia delante para acercar la pesa rusa al suelo. Trabaja los isquiotibiales, los glúteos y la zona lumbar, a la vez que mejora el equilibrio y la estabilidad.', 'accessory', 'intermediate', '["dumbbell","kettlebell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lower_back","gluteos"]'::jsonb, 'lower_back', 'peso-muerto-a-una-pierna-con-pesa-rusa', 'https://wger.de/media/exercise-images/1641/68d9488d-2596-420f-be0f-52aa70732c83.webp', 'https://wger.de/media/exercise-images/1641/68d9488d-2596-420f-be0f-52aa70732c83.webp', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Empuje de cadera con mancuerna', 'En este ejercicio te sientas en el suelo con una mancuerna apoyada sobre las caderas y luego empujas las caderas hacia arriba mientras contraes los glúteos. Es un ejercicio excelente para fortalecer los glúteos y mejorar la movilidad de la cadera.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'empuje-de-cadera-con-mancuerna', 'https://wger.de/media/exercise-images/1642/a81ad922-caf5-47f8-99b4-640cb0717436.webp', 'https://wger.de/media/exercise-images/1642/a81ad922-caf5-47f8-99b4-640cb0717436.webp', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Crunch con peso', 'El crunch con peso es una variante del crunch clásico que consiste en añadir resistencia (un peso) para aumentar la intensidad del trabajo abdominal. Túmbate (Opcional) Flexiona las rodillas para añadir dificultad (Opcional) Flexiona las rodillas y apoya los pies sobre un banco, una caja o algo similar (ángulo de 90 grados en las rodillas) Eleva la cabeza y el torso mientras curvas la espalda hacia delante (si no lo haces es un sit-up e implica también algunos músculos de la espalda). Cuanto más alto subas, más deberías sentir la contracción de los abdominales. Vuelve a la posición inicial y repite', 'core', 'intermediate', '["dumbbell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'crunch-con-peso', 'https://wger.de/media/exercise-images/1648/63ae02d6-6dd9-4e9e-84da-d4905e78a33c.jpg', 'https://wger.de/media/exercise-images/1648/63ae02d6-6dd9-4e9e-84da-d4905e78a33c.jpg', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Flexión lateral con mancuerna', 'En este ejercicio sostienes una mancuerna en una mano y te inclinas hacia un lado para trabajar los oblicuos en el costado del cuerpo. Puede realizarse de pie o sentado y se utiliza a menudo como ejercicio para fortalecer el core.', 'core', 'intermediate', '["dumbbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["core"]'::jsonb, 'core', 'flexion-lateral-con-mancuerna', 'https://wger.de/media/exercise-images/1650/1d7a5336-ec0b-4898-a474-78ba32789bf3.webp', 'https://wger.de/media/exercise-images/1650/1d7a5336-ec0b-4898-a474-78ba32789bf3.webp', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Zancada hacia atrás con mancuernas', 'En este ejercicio sostienes una mancuerna en cada mano y das un paso hacia atrás hasta una posición de zancada, para luego volver a ponerte de pie. Trabaja principalmente los glúteos, los isquiotibiales y los cuádriceps.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'zancada-hacia-atras-con-mancuernas', 'https://wger.de/media/exercise-images/1651/04ab2679-a04d-4d05-9c85-0d36e898328c.webp', 'https://wger.de/media/exercise-images/1651/04ab2679-a04d-4d05-9c85-0d36e898328c.webp', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Peso muerto rumano con mancuernas', 'En este ejercicio sostienes una mancuerna en cada mano y te inclinas hacia delante desde las caderas mientras mantienes la espalda recta, para luego volver a la posición de pie. Trabaja principalmente los isquiotibiales y los glúteos.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos"]'::jsonb, 'hamstrings', 'peso-muerto-rumano-con-mancuernas', 'https://wger.de/media/exercise-images/1652/0306c8c0-70cc-45d4-92de-6fa72ceaa834.webp', 'https://wger.de/media/exercise-images/1652/0306c8c0-70cc-45d4-92de-6fa72ceaa834.webp', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Sentadilla lateral con mancuerna', 'En este ejercicio sostienes una mancuerna en una mano y realizas una sentadilla mientras das un paso hacia un lado. Trabaja las piernas, los glúteos y la musculatura del core.', 'accessory', 'intermediate', '[]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'sentadilla-lateral-con-mancuerna', 'https://wger.de/media/exercise-images/1653/c10c4e17-1e14-4cf9-930b-cc3a614f15dd.webp', 'https://wger.de/media/exercise-images/1653/c10c4e17-1e14-4cf9-930b-cc3a614f15dd.webp', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Elevación lateral en máquina', 'La elevación lateral en máquina es un ejercicio de aislamiento que trabaja la parte media (lateral) del deltoides para conseguir unos hombros más anchos y definidos. La trayectoria fija de la máquina aporta mayor estabilidad que las mancuernas, lo que la hace ideal para principiantes o para quienes quieren centrarse únicamente en la activación muscular.', 'accessory', 'intermediate', '["gym_mat"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'elevacion-lateral-en-maquina', 'https://wger.de/media/exercise-images/1654/aa724a58-b3b5-4522-b278-1155416236a5.jpg', 'https://wger.de/media/exercise-images/1654/aa724a58-b3b5-4522-b278-1155416236a5.jpg', 'wger.de', 'CC-BY-SA 4', 'roneydya'),
  ('Sentadilla búlgara con mancuernas', 'La sentadilla búlgara consiste en realizar una sentadilla a una pierna con el pie trasero apoyado sobre una plataforma elevada. Elevar la pierna trasera sobre un banco genera inestabilidad y aumenta el rango de movimiento del ejercicio.', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["knee_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'sentadilla-bulgara-con-mancuernas', 'https://wger.de/media/exercise-images/1706/0c5243cc-2539-4005-aee0-d3a8c5d3a32c.jfif', 'https://wger.de/media/exercise-images/1706/0c5243cc-2539-4005-aee0-d3a8c5d3a32c.jfif', 'wger.de', 'CC-BY-SA 4', 'AlucardEvil40'),
  ('Remo sentado (máquina)', 'Mantén el pecho erguido y aprieta los omóplatos al final del movimiento. No te encorves hacia delante ni redondees la espalda durante la tracción.', 'accessory', 'intermediate', '[]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'remo-sentado-maquina', 'https://wger.de/media/exercise-images/1725/f0ebd44e-b8e1-400c-b598-ca371f3a07af.png', 'https://wger.de/media/exercise-images/1725/f0ebd44e-b8e1-400c-b598-ca371f3a07af.png', 'wger.de', 'CC-BY-SA 4', 'barry'),
  ('Jalón con brazos rectos (polea)', 'Mantén los brazos rectos pero no bloqueados, tirando con los dorsales, no con los hombros. No dejes que tus hombros se encojan hacia arriba durante el movimiento.', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'jalon-con-brazos-rectos-polea', 'https://wger.de/media/exercise-images/1726/2e7e541b-5f55-405a-ae78-3e71b3f42db4.png', 'https://wger.de/media/exercise-images/1726/2e7e541b-5f55-405a-ae78-3e71b3f42db4.png', 'wger.de', 'CC-BY-SA 4', 'barry'),
  ('Face pulls con banda amarilla/verde', 'Face pulls con banda – tracción horizontal de pie. Agarra la banda a la altura de la cara, tira de los codos hacia arriba y hacia afuera en dirección a tu cara mientras juntas los omóplatos. Trabaja la parte superior de la espalda y los hombros posteriores, y mejora la postura.', 'accessory', 'intermediate', '["resistance_band"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'face-pulls-con-banda-amarilla-verde', 'https://wger.de/media/exercise-images/1732/d13b9adb-968e-4f73-95e6-b16690bcf616.jpg', 'https://wger.de/media/exercise-images/1732/d13b9adb-968e-4f73-95e6-b16690bcf616.jpg', 'wger.de', 'CC-BY-SA 4', '54str'),
  ('Sentadilla isometrica al fallo', 'Sentadilla Isométrica al Fallo Definición La sentadilla isométrica al fallo es una variante de ejercicio de sentadilla donde mantienes una posición estática de sentadilla en un ángulo específico, sosteniendo la posición hasta que los músculos no pueden mantener más la contracción. Tipo de Contracción Isométrica (estática, sin movimiento) Grupos Musculares Principales Cuádriceps, glúteos, músculos posteriores del muslo Intensidad Muy alta, trabaja hasta el agotamiento muscular Beneficios Mejora fuerza, resistencia muscular, estabilidad Técnica de Ejecución Colócate en posición de sentadilla con los pies separados al ancho de las caderas Desciende hasta formar un ángulo de 90 grados en las rodillas Mantén esa posición completamente inmóvil Resiste hasta que los músculos fallen y no puedas so', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'sentadilla-isometrica-al-fallo', 'https://wger.de/media/exercise-images/1733/4ef77069-beb2-4504-a4f3-b181d5f35212.png', 'https://wger.de/media/exercise-images/1733/4ef77069-beb2-4504-a4f3-b181d5f35212.png', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Zancada con pesa rusa a una pierna', 'La "zancada con pesa rusa a una pierna" (o unilateral) es un ejercicio que mejora el equilibrio y la fuerza, implicando sujetar la pesa rusa cerca del pecho o con un brazo (mismo lado de la pierna de apoyo) y bajar en una zancada profunda, alternando piernas, o hacer variantes como sentadillas búlgaras con kettlebell, enfocándose en la estabilidad y el trabajo unilateral del tren inferior para fortalecer cuádriceps, glúteos y femorales, con versiones hacia adelante, atrás o laterales. Cómo hacer la zancada unilateral con pesa rusa Preparación: Ponte de pie con los pies juntos. Sujeta la pesa rusa con ambas manos por el asa, manteniéndola pegada al pecho, o sosténla con una sola mano (del mismo lado que la pierna que trabajará). Paso y descenso: Da un gran paso hacia adelante (o hacia atrás', 'accessory', 'intermediate', '["kettlebell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gemelos","gluteos","piernas"]'::jsonb, 'quadriceps', 'zancada-con-pesa-rusa-a-una-pierna', 'https://wger.de/media/exercise-images/1734/782e2fbb-1267-476d-a817-14f3b83e0564.png', 'https://wger.de/media/exercise-images/1734/782e2fbb-1267-476d-a817-14f3b83e0564.png', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Gluteo en prensa de lado con una pierna', 'Colócate en la máquina de prensa de piernas, pero en lugar de sentarte de frente, siéntate de lado para que la pierna que vas a trabajar quede alineada con la plataforma móvil. Asegura tu espalda contra el respaldo y agárrate bien de las asas para mantener la estabilidad Coloca el pie de la pierna de trabajo en la plataforma, asegurándote de que el talón quede bien apoyado y que la pierna esté casi completamente extendida, pero sin bloquear la rodilla. Desbloquea la seguridad de la máquina. Baja la plataforma lentamente y con control, doblando la rodilla y la cadera. El objetivo es llevar el talón lo más cerca posible de tu glúteo sin que la zona lumbar se despegue del respaldo. Es crucial mantener la espalda recta y no encorvarse. Empuja la plataforma hacia arriba usando principalmente la', 'accessory', 'intermediate', '["incline_bench"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["lower_back","gemelos","gluteos","piernas"]'::jsonb, 'lower_back', 'gluteo-en-prensa-de-lado-con-una-pierna', 'https://wger.de/media/exercise-images/1735/43bca7d9-2333-43f3-8554-2d0b39fa2a07.png', 'https://wger.de/media/exercise-images/1735/43bca7d9-2333-43f3-8554-2d0b39fa2a07.png', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Peso muerto a una pierna con mancuerna', 'Postura inicial: Sostén una mancuerna en la mano opuesta a la pierna que vas a utilizar como soporte. (Si te paras sobre la pierna derecha, sostén la mancuerna con la mano izquierda). Esto ayuda a contrarrestar el peso y activa los músculos estabilizadores. Mantén la espalda recta y el core activado. Mueve ligeramente el peso de tu cuerpo a la pierna de apoyo, con una mínima flexión en la rodilla. El movimiento (la bisagra de cadera): Inicia el movimiento doblando la cadera hacia atrás, no doblando las rodillas. Imagina que empujas un interruptor con los glúteos. Simultáneamente, extiende la pierna libre hacia atrás para mantener el equilibrio. Tu cuerpo debería formar una línea recta desde la cabeza hasta el talón de la pierna extendida. Baja la mancuerna hacia el suelo, manteniendo el br', 'accessory', 'intermediate', '["dumbbell"]'::jsonb, '["knee_injury","back_injury"]'::jsonb, '[]'::jsonb, '["lower_back","biceps","isquios","gluteos"]'::jsonb, 'lower_back', 'peso-muerto-a-una-pierna-con-mancuerna', 'https://wger.de/media/exercise-images/1736/aa724cc5-c485-4f3e-9d2a-0c6ae4baefbe.png', 'https://wger.de/media/exercise-images/1736/aa724cc5-c485-4f3e-9d2a-0c6ae4baefbe.png', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Dominadas en agarre neutro o remo TRX', 'Dominada: tracción vertical – se centra más en los dorsales (anchura de la espalda). Remo TRX: tracción horizontal – se centra más en los romboides/trapecios (grosor de la zona media de la espalda y postura).', 'accessory', 'intermediate', '["pull-up_bar"]'::jsonb, '["back_injury"]'::jsonb, '[]'::jsonb, '["lats","espalda"]'::jsonb, 'lats', 'dominadas-en-agarre-neutro-o-remo-trx', 'https://wger.de/media/exercise-images/1738/0529acdf-ede8-42a2-a3e5-8d0c57b7a0e1.jpg', 'https://wger.de/media/exercise-images/1738/0529acdf-ede8-42a2-a3e5-8d0c57b7a0e1.jpg', 'wger.de', 'CC-BY-SA 4', '54str'),
  ('Elevación lateral en maquina', 'Técnica de Ejecución La elevación lateral en máquina es un ejercicio diseñado para trabajar específicamente el músculo deltoides lateral (hombro medio) con un alto grado de control y seguridad. Pasos de Ejecución: Ajuste la máquina a su altura y posición correcta Siéntese con la espalda apoyada firmemente contra el respaldo Agarre los mangos laterales con un agarre cómodo Mantenga los codos ligeramente flexionados Eleve los brazos lateralmente hasta la altura de los hombros Pause brevemente en la posición superior Baje los brazos de manera controlada a la posición inicial Beneficios Aislamiento preciso del deltoides lateral Menor riesgo de lesiones en comparación con elevaciones libres Control del rango de movimiento Ideal para principiantes y rehabilitación Consejos Importantes Evite bala', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'elevacion-lateral-en-maquina-1744', 'https://wger.de/media/exercise-images/1744/cb9263c4-39fc-4261-8d30-a5d6d57841c1.jpg', 'https://wger.de/media/exercise-images/1744/cb9263c4-39fc-4261-8d30-a5d6d57841c1.jpg', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Elevación frontal en polea con barra', 'Posición inicial: Colócate de espaldas a la polea baja. Agarra la barra recta (o barra Z) con un agarre prono (palmas hacia abajo), a la anchura de los hombros. Da un paso atrás para que la barra quede a la altura de tus muslos, con las rodillas ligeramente flexionadas y el core activado para proteger la zona lumbar. Fase de elevación: Levanta la barra hacia adelante en un arco, manteniendo los codos semiflexionados. Sube hasta que la barra esté a la altura de los hombros o un poco por debajo. Contracción: En la parte superior, aprieta el deltoides anterior (parte frontal del hombro) durante un instante. Fase de descenso: Baja el peso de forma lenta y controlada hasta la posición inicial. La fase excéntrica (bajada) es crucial para el desarrollo muscular. Consejos clave Evita el balanceo: ', 'accessory', 'intermediate', '["cable_machine"]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["lower_back","hombros"]'::jsonb, 'lower_back', 'elevacion-frontal-en-polea-con-barra', 'https://wger.de/media/exercise-images/1745/9c92843a-6b90-428b-a868-9af4b11bad38.jpg', 'https://wger.de/media/exercise-images/1745/9c92843a-6b90-428b-a868-9af4b11bad38.jpg', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Sentadilla multipower', 'Técnica y ejecución La sentadilla en máquina Smith es una variante de la sentadilla con barra tradicional que utiliza una barra guiada con una trayectoria fija. Aquí tienes un desglose detallado de la técnica correcta: Posición inicial Colocación de los pies: Coloca los pies ligeramente por delante de la barra, separados aproximadamente a la anchura de los hombros. Posición de la barra: Apoya la barra sobre la parte superior del trapecio/hombros, similar a una sentadilla tradicional. Postura: Los pies pueden estar ligeramente inclinados hacia afuera para una rotación natural de la cadera. Movimiento de la sentadilla Descarga la barra girándola para soltarla de los ganchos de seguridad. Baja lentamente el cuerpo flexionando las rodillas y las caderas. Desciende hasta que los muslos estén pa', 'accessory', 'intermediate', '[]'::jsonb, '["knee_injury","back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","gluteos","piernas"]'::jsonb, 'quadriceps', 'sentadilla-multipower', 'https://wger.de/media/exercise-images/1747/af9647dd-04ec-4adf-9c07-4e33edb77277.jpg', 'https://wger.de/media/exercise-images/1747/af9647dd-04ec-4adf-9c07-4e33edb77277.jpg', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Abducción en máquina', 'Técnica y ejecución Posición inicial Posición sentada: Siéntese en la máquina con la espalda apoyada en la almohadilla. Colocación de las piernas: La parte interna de los muslos contra los puntos de resistencia acolchados de la máquina. Ajuste de la máquina: Ajuste la posición del asiento para alinear la articulación de la cadera con el punto de pivote de la máquina. Técnica de movimiento Comience con las piernas juntas o ligeramente presionadas contra las almohadillas internas. Empuje lentamente las piernas hacia afuera, separándolas. Muévase hasta alcanzar el máximo rango lateral cómodo. Haga una breve pausa en el punto final del movimiento. Regrese lentamente a la posición inicial con un movimiento controlado. Desglose biomecánico Activación muscular Activación principal: Glúteo medio (', 'accessory', 'intermediate', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["lower_back","gluteos"]'::jsonb, 'lower_back', 'abduccion-en-maquina', 'https://wger.de/media/exercise-images/1748/923a3ff7-c269-49bd-9f03-697151a40f06.jpg', 'https://wger.de/media/exercise-images/1748/923a3ff7-c269-49bd-9f03-697151a40f06.jpg', 'wger.de', 'CC-BY-SA 4', 'Tierrasverdes'),
  ('Sentadilla profunda con barra', 'La sentadilla profunda con barra es un ejercicio compuesto que trabaja varios grupos musculares del tren inferior, incluyendo los cuádriceps, los isquiotibiales y los glúteos. Una técnica correcta es crucial para maximizar los resultados y prevenir lesiones durante la sentadilla profunda con barra. Esto incluye mantener una postura al ancho de los hombros, crear tensión en todo el cuerpo, controlar el descenso y mantener una profundidad adecuada y una buena posición de las rodillas. Ejercicios de asistencia como la sentadilla frontal, la sentadilla goblet, la sentadilla dividida y la sentadilla búlgara pueden ayudar a mejorar tu rendimiento en la sentadilla profunda con barra al trabajar grupos musculares específicos y mejorar la técnica general. Para lograr nuevos récords personales en tu', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["knee_injury","back_injury","shoulder_injury"]'::jsonb, '[]'::jsonb, '["hamstrings","biceps","isquios","gluteos","piernas"]'::jsonb, 'hamstrings', 'sentadilla-profunda-con-barra', 'https://wger.de/media/exercise-images/1801/60043328-1cfb-4289-9865-aaf64d5aaa28.jpg', 'https://wger.de/media/exercise-images/1801/68720d5e-f422-47ac-81e4-c7b51144d302.jpg', 'wger.de', 'CC-BY-SA 4', 'fabrice'),
  ('Dorsiflexión de tobillo', 'Mueve tu rodilla adelante evitando separar el talón del suelo. Manten la posición un par de segundos y vuelve a la posición inicial', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'dorsiflexion-de-tobillo', 'https://wger.de/media/exercise-images/1804/691c69b8-c3db-4177-8435-dd3a97d88542.webp', 'https://wger.de/media/exercise-images/1804/691c69b8-c3db-4177-8435-dd3a97d88542.webp', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
  ('Zancada hacia atrás con barra', 'Paso 1: Ponte de pie con los pies separados al ancho de las caderas, sujetando una barra sobre la parte alta de la espalda. Paso 2: Mantén la espalda recta, el pecho arriba y el core activado. Paso 3: Da un paso hacia atrás con una pierna y baja el cuerpo flexionando ambas rodillas. Asegúrate de que la rodilla trasera casi toque el suelo. Paso 4: Empuja con el pie trasero para volver a la posición inicial. Paso 5: Repite el movimiento con la otra pierna. Continúa alternando entre las piernas durante las repeticiones deseadas.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'zancada-hacia-atras-con-barra', 'https://wger.de/media/exercise-images/1830/3b6c547c-ab3d-4472-93cf-561710279eab.jpg', 'https://wger.de/media/exercise-images/1830/3b6c547c-ab3d-4472-93cf-561710279eab.jpg', 'wger.de', 'CC-BY-SA 4', ''),
  ('Press de pecho declinado en Hammer Strength', 'Siéntate erguido en una máquina Hammer Strength de press de pecho declinado, juntando los omóplatos y apoyando firmemente los talones en el suelo, bajo las rodillas. El respaldo debe estar en contacto con la cabeza, los hombros y los glúteos en todo momento. Agarra los manillares con un agarre prono, algo más anchos que el ancho de los hombros, justo por debajo del pecho. Mantén el core activado respirando hacia el abdomen y contrayendo los abdominales, y empuja con las palmas para extender los codos, manteniéndolos en un ángulo de 45 grados respecto al torso. Una vez que los brazos estén completamente extendidos, vuelve a la posición inicial.', 'accessory', 'intermediate', '[]'::jsonb, '["shoulder_injury"]'::jsonb, '[]'::jsonb, '["pectorals","pecho"]'::jsonb, 'pectorals', 'press-de-pecho-declinado-en-hammer-strength', 'https://wger.de/media/exercise-images/1831/2d9d509f-707b-4132-961e-91a2459ca198.jpg', 'https://wger.de/media/exercise-images/1831/2d9d509f-707b-4132-961e-91a2459ca198.jpg', 'wger.de', 'CC-BY-SA 4', ''),
  ('Estiramiento con rotación externa', 'Siéntate con las plantas de los pies juntas y una rodilla elevada completamente hacia el lado del cuerpo. Apoya el codo sobre la rodilla elevada, flexiónalo a 90 grados y apunta la mano directamente hacia adelante, sujetando tu barra o mancuerna. Mantén el hombro descendido y retraído, y eleva la mano hasta que el antebrazo quede vertical, como si fueras a saludar a alguien como un robot. Baja la mano a la posición inicial y repite.', 'accessory', 'intermediate', '["barbell"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["deltoids","hombros"]'::jsonb, 'deltoids', 'estiramiento-con-rotacion-externa', 'https://wger.de/media/exercise-images/1835/ca4a0b7e-9fdd-4173-843a-f0392824abe1.jpg', 'https://wger.de/media/exercise-images/1835/ca4a0b7e-9fdd-4173-843a-f0392824abe1.jpg', 'wger.de', 'CC-BY-SA 4', 'Croak6728'),
  ('Foam Roller Gemelos', 'Mueve sobre el foam roller tus gemelos lentamente', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["calves","gemelos"]'::jsonb, 'calves', 'foam-roller-gemelos', 'https://wger.de/media/exercise-images/1854/ccd3c18e-c864-426f-8176-15dce14305e3.webp', 'https://wger.de/media/exercise-images/1854/ccd3c18e-c864-426f-8176-15dce14305e3.webp', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
  ('Foam Roller isquitobiales', 'Mueve sobre el foam roller tus isquitobiales lentamente', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps"]'::jsonb, 'quadriceps', 'foam-roller-isquitobiales', 'https://wger.de/media/exercise-images/1855/a6597ed8-1613-4458-ba56-4b63bc946a35.webp', 'https://wger.de/media/exercise-images/1855/a6597ed8-1613-4458-ba56-4b63bc946a35.webp', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
  ('Foam Roller Tibial anterior', 'Deslice el tibial anterior lentamente sobre el Foam Roller', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps"]'::jsonb, 'quadriceps', 'foam-roller-tibial-anterior', 'https://wger.de/media/exercise-images/1856/19c31c63-4968-4887-b8e6-4127be27fdde.jpg', 'https://wger.de/media/exercise-images/1856/19c31c63-4968-4887-b8e6-4127be27fdde.jpg', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
  ('Foam Roller Cintillar iliotibial', 'Deslizate sobr el Foam Roller sobre tu Cintilla iliotibial', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'foam-roller-cintillar-iliotibial', 'https://wger.de/media/exercise-images/1857/92291128-cc7e-4f70-9663-80840c516fc9.jpg', 'https://wger.de/media/exercise-images/1857/92291128-cc7e-4f70-9663-80840c516fc9.jpg', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
  ('Foam Roller cuadriceps', 'Deslizate sobre el Foam Roller sobre tus cuadriceps', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["quadriceps","piernas"]'::jsonb, 'quadriceps', 'foam-roller-cuadriceps', 'https://wger.de/media/exercise-images/1858/058b6fdb-8093-4b6d-a504-cbf869f3e3d3.jpg', 'https://wger.de/media/exercise-images/1858/058b6fdb-8093-4b6d-a504-cbf869f3e3d3.jpg', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
  ('Foam roller Gluteo', 'Deslizate sobre el Foam Roller sobre tu glúteo. Es castellano por favor corrector', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["glutes","gluteos"]'::jsonb, 'glutes', 'foam-roller-gluteo', 'https://wger.de/media/exercise-images/1859/2465d5eb-c249-454d-93eb-58aa13bdc080.webp', 'https://wger.de/media/exercise-images/1859/2465d5eb-c249-454d-93eb-58aa13bdc080.webp', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
  ('Foam Roller Aductores', 'Deslizate sobre el Foam Roller sobre tus Aductores. Es castellano por favor', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["adductors"]'::jsonb, 'adductors', 'foam-roller-aductores', 'https://wger.de/media/exercise-images/1860/f0410e66-28d5-455f-90f3-d078e0988460.avif', 'https://wger.de/media/exercise-images/1860/f0410e66-28d5-455f-90f3-d078e0988460.avif', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
