  ('Lunge with Twist Stretch', 'Ejercicio de entrenamiento guiado.', 'accessory', 'intermediate', '["none_(bodyweight_exercise)"]'::jsonb, '["knee_injury"]'::jsonb, '[]'::jsonb, '["quadriceps"]'::jsonb, 'quadriceps', 'lunge-with-twist-stretch', 'https://wger.de/media/exercise-images/1868/446e7065-215d-4a91-9da7-9416101442bb.png', 'https://wger.de/media/exercise-images/1868/446e7065-215d-4a91-9da7-9416101442bb.png', 'wger.de', 'CC-BY-SA 4', 'Davidgj32'),
